// Environment variables configuration
export const ENV_CONFIG = {
  SUPABASE_URL: import.meta.env.VITE_SUPABASE_URL || 'https://nzksnfoxrzzkoppcehpe.supabase.co',
  SUPABASE_ANON_KEY: import.meta.env.VITE_SUPABASE_ANON_KEY || 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im56a3NuZm94cnp6a29wcGNlaHBlIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjMwNDcwNzUsImV4cCI6MjA3ODYyMzA3NX0.VJAzcZ0yLa3DxE8lJOK1z20zMDegv7aKLS23cobOxSg',
  APP_NAME: import.meta.env.VITE_APP_NAME || 'Anime Social App',
  APP_ENV: import.meta.env.VITE_APP_ENV || 'production',
} as const;

// Validate environment variables
export function validateEnvironment() {
  const errors: string[] = [];
  
  if (!ENV_CONFIG.SUPABASE_URL || ENV_CONFIG.SUPABASE_URL === 'undefined') {
    errors.push('VITE_SUPABASE_URL is not configured');
  }
  
  if (!ENV_CONFIG.SUPABASE_ANON_KEY || ENV_CONFIG.SUPABASE_ANON_KEY === 'undefined') {
    errors.push('VITE_SUPABASE_ANON_KEY is not configured');
  }
  
  if (errors.length > 0) {
    console.error('❌ Environment Configuration Errors:');
    errors.forEach(error => console.error(`   - ${error}`));
    console.error('Please ensure all required environment variables are set in your deployment.');
    return false;
  }
  
  console.log('✅ Environment variables validated successfully');
  return true;
}

// Check if running in production
export const isProduction = ENV_CONFIG.APP_ENV === 'production';

// Debug information
export function getEnvDebugInfo() {
  return {
    appName: ENV_CONFIG.APP_NAME,
    environment: ENV_CONFIG.APP_ENV,
    supabaseUrl: ENV_CONFIG.SUPABASE_URL ? 'Configured' : 'Missing',
    supabaseKey: ENV_CONFIG.SUPABASE_ANON_KEY ? 'Configured' : 'Missing',
    isProduction: isProduction,
    timestamp: new Date().toISOString(),
  };
}