import { useState } from 'react'
import { Link, useLocation } from 'react-router-dom'
import { Home, Users, PlusCircle, Bell, User } from 'lucide-react'
import { CreatePostModal } from './CreatePostModal'
import { ThemeToggle } from './ThemeToggle'
import { toast } from 'sonner'

export function MobileNav() {
  const location = useLocation()
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false)

  const navItems = [
    {
      path: '/',
      icon: Home,
      label: '主页',
      isCreate: false
    },
    {
      path: '/following',
      icon: Users,
      label: '关注',
      isCreate: false
    },
    {
      path: '',
      icon: PlusCircle,
      label: '发布',
      isCreate: true
    },
    {
      path: '/notifications',
      icon: Bell,
      label: '消息',
      isCreate: false
    },
    {
      path: '/profile',
      icon: User,
      label: '我的',
      isCreate: false
    }
  ]

  const handleCreateClick = () => {
    setIsCreateModalOpen(true)
  }

  const handlePostSuccess = () => {
    toast.success('发布成功！')
    setIsCreateModalOpen(false)
  }

  return (
    <>
      {/* 移动端底部导航 */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white/95 dark:bg-gray-900/95 backdrop-blur-sm border-t border-gray-200 dark:border-gray-700 z-50 safe-area-pb">
        <div className="flex items-center justify-around py-2 px-2">
          {navItems.map((item, index) => {
            const Icon = item.icon
            const isActive = location.pathname === item.path
            const isCreateButton = item.isCreate

            if (isCreateButton) {
              return (
                <button
                  key={index}
                  onClick={handleCreateClick}
                  className="flex flex-col items-center justify-center p-2 text-pink-500 hover:text-pink-600 transition-all duration-200 transform hover:scale-110 active:scale-95"
                >
                  <div className="relative">
                    <Icon className="w-8 h-8 drop-shadow-sm" />
                    <div className="absolute -inset-1 bg-pink-500/10 rounded-full blur-sm" />
                  </div>
                  <span className="text-xs mt-1 font-medium">{item.label}</span>
                </button>
              )
            }

            return (
              <Link
                key={index}
                to={item.path}
                className={`flex flex-col items-center justify-center p-2 transition-all duration-200 relative group ${
                  isActive
                    ? 'text-pink-500'
                    : 'text-gray-600 dark:text-gray-400 hover:text-pink-500'
                }`}
              >
                <div className="relative">
                  <Icon className="w-6 h-6 transition-transform group-hover:scale-110" />
                  {isActive && (
                    <div className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-1 h-1 bg-pink-500 rounded-full" />
                  )}
                </div>
                <span className="text-xs mt-1 font-medium">{item.label}</span>
              </Link>
            )
          })}
        </div>
      </div>

      {/* 发布模态框 */}
      <CreatePostModal
        isOpen={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        onSuccess={handlePostSuccess}
      />
    </>
  )
}