import { useState } from 'react'
import { supabase } from '../lib/supabase'
import { toast } from 'sonner'

export function PostCreationTest() {
  const [isTesting, setIsTesting] = useState(false)
  const [testResults, setTestResults] = useState<string[]>([])

  const addResult = (message: string) => {
    setTestResults(prev => [...prev, `${new Date().toLocaleTimeString()}: ${message}`])
  }

  const runCreationTest = async () => {
    setIsTesting(true)
    setTestResults([])
    
    try {
      addResult('开始测试帖子创建功能...')
      
      // 1. 检查用户认证状态
      addResult('检查用户认证状态...')
      const { data: { user }, error: authError } = await supabase.auth.getUser()
      
      if (authError || !user) {
        addResult(`❌ 用户认证失败: ${authError?.message || '未登录'}`)
        return
      }
      addResult(`✅ 用户认证成功: ${user.email}`)
      addResult(`   用户ID: ${user.id}`)
      
      // 2. 测试数据库连接
      addResult('测试数据库连接...')
      const { data: connectionTest, error: connectionError } = await supabase
        .from('posts')
        .select('id')
        .limit(1)
        
      if (connectionError) {
        addResult(`❌ 数据库连接失败: ${connectionError.message}`)
        return
      }
      addResult('✅ 数据库连接成功')
      
      // 3. 检查posts表权限
      addResult('检查posts表权限...')
      const { data: permissionTest, error: permissionError } = await supabase
        .from('posts')
        .insert({
          user_id: user.id,
          content: '测试帖子 - ' + new Date().toISOString(),
          images: [],
          videos: []
        })
        .select()
        .single()
        
      if (permissionError) {
        addResult(`❌ Posts表权限测试失败: ${permissionError.message}`)
        addResult(`   错误代码: ${permissionError.code || '无'}`)
        addResult(`   错误详情: ${JSON.stringify(permissionError, null, 2)}`)
      } else {
        addResult('✅ Posts表权限测试成功')
        addResult(`   创建的帖子ID: ${permissionTest.id}`)
        
        // 清理测试数据
        if (permissionTest.id) {
          const { error: deleteError } = await supabase
            .from('posts')
            .delete()
            .eq('id', permissionTest.id)
            
          if (deleteError) {
            addResult(`⚠️ 清理测试数据失败: ${deleteError.message}`)
          } else {
            addResult('✅ 测试数据已清理')
          }
        }
      }
      
      // 4. 检查存储桶权限
      addResult('检查存储桶权限...')
      try {
        const { data: buckets, error: bucketError } = await supabase
          .storage
          .listBuckets()
          
        if (bucketError) {
          addResult(`❌ 存储桶列表失败: ${bucketError.message}`)
        } else {
          addResult(`✅ 存储桶列表成功: ${buckets?.length || 0} 个存储桶`)
          const postsBucket = buckets?.find(b => b.id === 'posts')
          if (postsBucket) {
            addResult(`   Posts存储桶: ${postsBucket.id} (public: ${postsBucket.public})`)
          } else {
            addResult(`⚠️ Posts存储桶未找到`)
          }
        }
      } catch (storageError) {
        addResult(`❌ 存储桶测试异常: ${storageError}`)
      }
      
      addResult('测试完成！')
      
    } catch (error) {
      addResult(`❌ 测试异常: ${error}`)
    } finally {
      setIsTesting(false)
    }
  }

  return (
    <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
      <h3 className="text-lg font-semibold mb-4 text-gray-800 dark:text-gray-200">
        帖子创建功能诊断
      </h3>
      
      <button
        onClick={runCreationTest}
        disabled={isTesting}
        className="bg-blue-500 text-white px-4 py-2 rounded-lg hover:bg-blue-600 disabled:opacity-50 mb-4"
      >
        {isTesting ? '测试中...' : '运行诊断测试'}
      </button>
      
      <div className="bg-gray-100 dark:bg-gray-900 p-4 rounded-lg max-h-64 overflow-y-auto">
        <h4 className="font-medium mb-2 text-gray-700 dark:text-gray-300">测试结果:</h4>
        {testResults.length === 0 ? (
          <p className="text-gray-500 dark:text-gray-400">点击按钮开始测试</p>
        ) : (
          <div className="space-y-1 text-sm">
            {testResults.map((result, index) => (
              <div key={index} className="font-mono text-gray-600 dark:text-gray-400">
                {result}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}