import { useState, useEffect } from 'react'
import { Heart, MessageCircle, Star, UserPlus } from 'lucide-react'
import { supabase } from '../lib/supabase'
import { toast } from 'sonner'

interface Notification {
  id: string
  type: 'like' | 'comment' | 'favorite' | 'follow'
  user_id: string
  user_name: string
  user_avatar: string
  post_id?: string
  post_content?: string
  comment_content?: string
  created_at: string
  is_read: boolean
}

export function NotificationsPage() {
  const [notifications, setNotifications] = useState<Notification[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [activeTab, setActiveTab] = useState<'all' | 'unread'>('all')

  const fetchNotifications = async () => {
    try {
      setIsLoading(true)
      
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) {
        toast.error('请先登录')
        setNotifications([])
        return
      }

      // 获取点赞通知
      const { data: likesData, error: likesError } = await supabase
        .from('likes')
        .select(`
          id,
          created_at,
          user:users!likes_user_id_fkey(id, username, avatar_url),
          post:posts!likes_post_id_fkey(id, content)
        `)
        .eq('post.user_id', user.id)
        .order('created_at', { ascending: false })
        .limit(20)

      // 获取收藏通知
      const { data: favoritesData, error: favoritesError } = await supabase
        .from('favorites')
        .select(`
          id,
          created_at,
          user:users!favorites_user_id_fkey(id, username, avatar_url),
          post:posts!favorites_post_id_fkey(id, content)
        `)
        .eq('post.user_id', user.id)
        .order('created_at', { ascending: false })
        .limit(20)

      // 获取评论通知
      const { data: commentsData, error: commentsError } = await supabase
        .from('comments')
        .select(`
          id,
          content,
          created_at,
          user:users!comments_user_id_fkey(id, username, avatar_url),
          post:posts!comments_post_id_fkey(id, content)
        `)
        .eq('post.user_id', user.id)
        .order('created_at', { ascending: false })
        .limit(20)

      // 获取关注通知
      const { data: followsData, error: followsError } = await supabase
        .from('follows')
        .select(`
          id,
          created_at,
          follower:users!follows_follower_id_fkey(id, username, avatar_url)
        `)
        .eq('following_id', user.id)
        .order('created_at', { ascending: false })
        .limit(20)

      // 合并所有通知
      const allNotifications: Notification[] = []

      // 处理点赞通知
      likesData?.forEach(like => {
        const user = Array.isArray(like.user) ? like.user[0] : like.user
        const post = Array.isArray(like.post) ? like.post[0] : like.post
        
        allNotifications.push({
          id: `like_${like.id}`,
          type: 'like',
          user_id: user?.id || '',
          user_name: user?.username || '未知用户',
          user_avatar: user?.avatar_url || '',
          post_id: post?.id,
          post_content: post?.content,
          created_at: like.created_at,
          is_read: false
        })
      })

      // 处理收藏通知
      favoritesData?.forEach(favorite => {
        const user = Array.isArray(favorite.user) ? favorite.user[0] : favorite.user
        const post = Array.isArray(favorite.post) ? favorite.post[0] : favorite.post
        
        allNotifications.push({
          id: `favorite_${favorite.id}`,
          type: 'favorite',
          user_id: user?.id || '',
          user_name: user?.username || '未知用户',
          user_avatar: user?.avatar_url || '',
          post_id: post?.id,
          post_content: post?.content,
          created_at: favorite.created_at,
          is_read: false
        })
      })

      // 处理评论通知
      commentsData?.forEach(comment => {
        const user = Array.isArray(comment.user) ? comment.user[0] : comment.user
        const post = Array.isArray(comment.post) ? comment.post[0] : comment.post
        
        allNotifications.push({
          id: `comment_${comment.id}`,
          type: 'comment',
          user_id: user?.id || '',
          user_name: user?.username || '未知用户',
          user_avatar: user?.avatar_url || '',
          post_id: post?.id,
          post_content: post?.content,
          comment_content: comment.content,
          created_at: comment.created_at,
          is_read: false
        })
      })

      // 处理关注通知
      followsData?.forEach(follow => {
        const follower = Array.isArray(follow.follower) ? follow.follower[0] : follow.follower
        
        allNotifications.push({
          id: `follow_${follow.id}`,
          type: 'follow',
          user_id: follower?.id || '',
          user_name: follower?.username || '未知用户',
          user_avatar: follower?.avatar_url || '',
          created_at: follow.created_at,
          is_read: false
        })
      })

      // 按时间排序
      allNotifications.sort((a, b) => 
        new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
      )

      setNotifications(allNotifications)
    } catch (error) {
      console.error('获取通知失败:', error)
      toast.error('获取通知失败，请稍后重试')
      setNotifications([])
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    fetchNotifications()
  }, [])

  const getNotificationIcon = (type: string) => {
    switch (type) {
      case 'like':
        return <Heart className="w-5 h-5 text-red-500" />
      case 'comment':
        return <MessageCircle className="w-5 h-5 text-blue-500" />
      case 'favorite':
        return <Star className="w-5 h-5 text-yellow-500" />
      case 'follow':
        return <UserPlus className="w-5 h-5 text-green-500" />
      default:
        return <Heart className="w-5 h-5 text-gray-500" />
    }
  }

  const getNotificationText = (notification: Notification) => {
    switch (notification.type) {
      case 'like':
        return `赞了你的帖子`
      case 'comment':
        return `评论了你的帖子: "${notification.comment_content}"`
      case 'favorite':
        return `收藏了你的帖子`
      case 'follow':
        return `开始关注你`
      default:
        return `有新的互动`
    }
  }

  const formatTime = (dateString: string) => {
    const date = new Date(dateString)
    const now = new Date()
    const diff = now.getTime() - date.getTime()
    const minutes = Math.floor(diff / 60000)
    const hours = Math.floor(diff / 3600000)
    const days = Math.floor(diff / 86400000)

    if (minutes < 1) return '刚刚'
    if (minutes < 60) return `${minutes}分钟前`
    if (hours < 24) return `${hours}小时前`
    return `${days}天前`
  }

  const filteredNotifications = activeTab === 'unread' 
    ? notifications.filter(n => !n.is_read)
    : notifications

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-pink-50 to-blue-50 p-6">
        <div className="max-w-4xl mx-auto">
          <div className="mb-6">
            <h1 className="text-2xl font-bold text-gray-800 mb-2">消息通知</h1>
            <p className="text-gray-600">查看你的最新互动消息</p>
          </div>
          
          {/* 标签页 */}
          <div className="flex space-x-4 mb-6">
            <button className="px-4 py-2 bg-pink-500 text-white rounded-full font-medium">
              全部
            </button>
            <button className="px-4 py-2 text-gray-600 hover:text-pink-500 transition-colors">
              未读
            </button>
          </div>

          <div className="space-y-4">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-white rounded-2xl p-4 animate-pulse">
                <div className="flex items-center space-x-3">
                  <div className="w-12 h-12 bg-gray-200 rounded-full"></div>
                  <div className="flex-1 space-y-2">
                    <div className="h-4 bg-gray-200 rounded w-3/4"></div>
                    <div className="h-3 bg-gray-200 rounded w-1/2"></div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-white to-pink-50 pb-20 md:pb-0">
      <div className="max-w-4xl mx-auto p-6">
        <div className="mb-6">
          <h1 className="text-2xl font-bold text-gray-800 mb-2">消息通知</h1>
          <p className="text-gray-600">查看你的最新互动消息</p>
        </div>
        
        {/* 标签页 */}
        <div className="flex space-x-4 mb-6">
          <button 
            onClick={() => setActiveTab('all')}
            className={`px-4 py-2 rounded-full font-medium transition-colors ${
              activeTab === 'all' 
                ? 'bg-pink-500 text-white' 
                : 'text-gray-600 hover:text-pink-500'
            }`}
          >
            全部 ({notifications.length})
          </button>
          <button 
            onClick={() => setActiveTab('unread')}
            className={`px-4 py-2 rounded-full font-medium transition-colors ${
              activeTab === 'unread' 
                ? 'bg-pink-500 text-white' 
                : 'text-gray-600 hover:text-pink-500'
            }`}
          >
            未读 ({notifications.filter(n => !n.is_read).length})
          </button>
        </div>

        <div className="space-y-4">
          {filteredNotifications.length === 0 ? (
            <div className="text-center py-12">
              <div className="text-6xl mb-4">🔔</div>
              <h3 className="text-xl font-semibold text-gray-600 mb-2">
                {activeTab === 'unread' ? '暂无未读消息' : '暂无消息通知'}
              </h3>
              <p className="text-gray-500">
                {activeTab === 'unread' ? '已查看所有消息' : '还没有收到任何互动消息'}
              </p>
            </div>
          ) : (
            filteredNotifications.map((notification) => (
              <div 
                key={notification.id}
                className={`bg-white rounded-2xl p-4 transition-all duration-200 hover:shadow-md ${
                  !notification.is_read ? 'border-l-4 border-pink-500' : ''
                }`}
              >
                <div className="flex items-center space-x-3">
                  <img
                    src={notification.user_avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${notification.user_name}`}
                    alt={notification.user_name}
                    className="w-12 h-12 rounded-full object-cover"
                  />
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center space-x-2">
                      {getNotificationIcon(notification.type)}
                      <span className="font-semibold text-gray-800 truncate">
                        {notification.user_name}
                      </span>
                    </div>
                    <p className="text-sm text-gray-600 mt-1">
                      {getNotificationText(notification)}
                    </p>
                    {notification.post_content && (
                      <p className="text-xs text-gray-500 mt-2 line-clamp-2">
                        "{notification.post_content}"
                      </p>
                    )}
                    <p className="text-xs text-gray-400 mt-2">
                      {formatTime(notification.created_at)}
                    </p>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  )
}