import { useState } from 'react'
import { supabase, supabaseConfig } from '../lib/supabase'
import { useAuthStore } from '../stores/authStore'
import { Toaster, toast } from 'sonner'

export function LoginForm() {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [isSignUp, setIsSignUp] = useState(false)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsLoading(true)

    try {
      if (isSignUp) {
        const { data, error } = await supabase.auth.signUp({
          email,
          password,
        })
        if (error) throw error
        toast.success('注册成功！请检查邮箱验证邮件')
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email,
          password,
        })
        if (error) throw error
        toast.success('登录成功！')
      }
    } catch (error: any) {
      console.error('Auth error:', error)
      let errorMessage = isSignUp ? '注册失败' : '登录失败'
      
      // 提供更详细的错误信息
      if (error?.message) {
        if (error.message.includes('Invalid login credentials')) {
          errorMessage = '邮箱或密码错误'
        } else if (error.message.includes('User already registered')) {
          errorMessage = '该邮箱已被注册'
        } else if (error.message.includes('Email not confirmed')) {
          errorMessage = '邮箱未验证，请检查邮箱'
        } else if (error.message.includes('network error')) {
          errorMessage = '网络连接失败，请检查网络'
        } else {
          errorMessage = error.message
        }
      }
      
      toast.error(errorMessage)
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-pink-100 to-blue-100">
      <Toaster position="top-center" />
      <div className="bg-white p-8 rounded-3xl shadow-2xl w-full max-w-md">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-gray-800 mb-2">
            {isSignUp ? '加入二次元世界' : '欢迎回来'}
          </h1>
          <p className="text-gray-600">
            {isSignUp ? '创建你的专属账号' : '继续你的二次元之旅'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              邮箱地址
            </label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-pink-500 focus:border-transparent"
              placeholder="请输入邮箱地址"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              密码
            </label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-pink-500 focus:border-transparent"
              placeholder="请输入密码"
              required
            />
          </div>

          <button
            type="submit"
            disabled={isLoading}
            className="w-full bg-gradient-to-r from-pink-500 to-blue-500 text-white py-3 rounded-xl font-semibold hover:from-pink-600 hover:to-blue-600 transform hover:scale-105 transition-all duration-200 disabled:opacity-50"
          >
            {isLoading ? '处理中...' : (isSignUp ? '注册' : '登录')}
          </button>
        </form>

        <div className="text-center mt-6">
          <button
            onClick={() => setIsSignUp(!isSignUp)}
            className="text-pink-600 hover:text-pink-800 font-medium"
          >
            {isSignUp ? '已有账号？立即登录' : '还没有账号？立即注册'}
          </button>
        </div>
      </div>
    </div>
  )
}