import { useState, useEffect } from 'react'
import { PostCard } from '../components/PostCard'
import { Post, User } from '../types'
import { supabase } from '../lib/supabase'
import { toast } from 'sonner'
import { Search, UserPlus, Users, Hash } from 'lucide-react'

interface Circle {
  id: string
  name: string
  description: string
  member_count: number
  created_at: string
}

export function FollowingPage() {
  const [posts, setPosts] = useState<Post[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [activeTab, setActiveTab] = useState<'posts' | 'users' | 'circles'>('posts')
  const [availableUsers, setAvailableUsers] = useState<User[]>([])
  const [availableCircles, setAvailableCircles] = useState<Circle[]>([])
  const [followedUsers, setFollowedUsers] = useState<string[]>([])
  const [followedCircles, setFollowedCircles] = useState<string[]>([])
  const [searchQuery, setSearchQuery] = useState('')
  const [isLoadingUsers, setIsLoadingUsers] = useState(false)
  const [isLoadingCircles, setIsLoadingCircles] = useState(false)

  const fetchFollowingPosts = async () => {
    try {
      setIsLoading(true)
      
      // 获取当前用户信息
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) {
        toast.error('请先登录')
        setPosts([])
        return
      }

      // 获取用户关注的用户列表
      const { data: followingData, error: followingError } = await supabase
        .from('follows')
        .select('following_id')
        .eq('follower_id', user.id)

      if (followingError) {
        throw new Error('获取关注列表失败')
      }

      // 确保 followingData 存在且是数组
      if (!followingData || !Array.isArray(followingData)) {
        setFollowedUsers([])
        setPosts([])
        return
      }

      setFollowedUsers(followingData.map(f => f.following_id))

      if (followingData.length === 0) {
        setPosts([])
        return
      }

      const followingIds = followingData.map(f => f.following_id)

      // 获取关注用户的帖子
      const { data: postsData, error: postsError } = await supabase
        .from('posts')
        .select('*')
        .in('user_id', followingIds)
        .order('created_at', { ascending: false })
        .limit(20)

      if (postsError) {
        throw new Error('获取帖子失败')
      }

      // 验证数据完整性
      if (!postsData || !Array.isArray(postsData) || postsData.length === 0) {
        setPosts([])
        return
      }

      // 获取用户信息和标签信息
      const postsWithDetails = await Promise.all(
        postsData.map(async (post) => {
          try {
            // 获取用户信息
            const { data: userData, error: userError } = await supabase
              .from('users')
              .select('id, username, avatar_url')
              .eq('id', post.user_id)
              .single()

            if (userError) {
              console.warn(`获取用户 ${post.user_id} 信息失败:`, userError)
            }

            // 获取标签信息
            const { data: postTagsData, error: tagsError } = await supabase
              .from('post_tags')
              .select('tag:tags(id, name, category, usage_count)')
              .eq('post_id', post.id)

            if (tagsError) {
              console.warn(`获取帖子 ${post.id} 标签失败:`, tagsError)
            }

            let is_liked = false
            let is_favorited = false

            // 检查是否点赞
            const { data: likeData } = await supabase
              .from('likes')
              .select('id')
              .eq('user_id', user.id)
              .eq('post_id', post.id)
              .maybeSingle()
            
            is_liked = !!likeData

            // 检查是否收藏
            const { data: favoriteData } = await supabase
              .from('favorites')
              .select('id')
              .eq('user_id', user.id)
              .eq('post_id', post.id)
              .maybeSingle()
            
            is_favorited = !!favoriteData

            return {
              ...post,
              user: userData || { id: post.user_id, username: '未知用户', avatar_url: null },
              tags: postTagsData?.map((pt: any) => pt.tag) || [],
              is_liked,
              is_favorited,
              images: Array.isArray(post.images) ? post.images : [],
              videos: Array.isArray(post.videos) ? post.videos : [],
              comments_count: post.comments_count || 0,
              likes_count: post.likes_count || 0
            }
          } catch (error) {
            console.error(`处理帖子 ${post.id} 时出错:`, error)
            // 确保返回有效的帖子对象，避免 undefined 错误
            return {
              id: post.id,
              user_id: post.user_id,
              content: post.content || '',
              images: Array.isArray(post.images) ? post.images : [],
              videos: Array.isArray(post.videos) ? post.videos : [],
              likes_count: post.likes_count || 0,
              comments_count: post.comments_count || 0,
              created_at: post.created_at,
              updated_at: post.updated_at,
              user: { id: post.user_id, username: '未知用户', avatar_url: null },
              tags: [],
              is_liked: false,
              is_favorited: false
            }
          }
        })
      )

      setPosts(postsWithDetails)
    } catch (error) {
      console.error('获取关注帖子失败:', error)
      toast.error('获取关注帖子失败，请稍后重试')
      setPosts([])
    } finally {
      setIsLoading(false)
    }
  }

  const fetchAvailableUsers = async () => {
    try {
      setIsLoadingUsers(true)
      
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) {
        toast.error('请先登录')
        return
      }

      let query = supabase
        .from('users')
        .select('id, email, username, avatar_url, bio, role, created_at, updated_at')
        .neq('id', user.id)
        .order('created_at', { ascending: false })
        .limit(50)

      if (searchQuery.trim()) {
        query = query.ilike('username', `%${searchQuery.trim()}%`)
      }

      const { data: usersData, error: usersError } = await query

      if (usersError) {
        throw new Error('获取用户列表失败')
      }

      // 获取用户统计信息
      const usersWithStats = await Promise.all(
        (usersData || []).map(async (user) => {
          try {
            // 获取关注者数量
            const { count: followersCount } = await supabase
              .from('follows')
              .select('*', { count: 'exact', head: true })
              .eq('following_id', user.id)

            // 获取关注数量
            const { count: followingCount } = await supabase
              .from('follows')
              .select('*', { count: 'exact', head: true })
              .eq('follower_id', user.id)

            // 获取帖子数量
            const { count: postsCount } = await supabase
              .from('posts')
              .select('*', { count: 'exact', head: true })
              .eq('user_id', user.id)

            return {
              ...user,
              followers_count: followersCount || 0,
              following_count: followingCount || 0,
              posts_count: postsCount || 0
            }
          } catch (error) {
            console.warn(`获取用户 ${user.id} 统计信息失败:`, error)
            return {
              ...user,
              followers_count: 0,
              following_count: 0,
              posts_count: 0
            }
          }
        })
      )

      setAvailableUsers(usersWithStats)
    } catch (error) {
      console.error('获取用户列表失败:', error)
      toast.error('获取用户列表失败')
    } finally {
      setIsLoadingUsers(false)
    }
  }

  const fetchAvailableCircles = async () => {
    try {
      setIsLoadingCircles(true)
      
      // 模拟圈子数据 - 在实际应用中，你需要创建圈子表
      const mockCircles: Circle[] = [
        {
          id: '1',
          name: '摄影爱好者',
          description: '分享摄影技巧、作品展示和交流心得',
          member_count: 1250,
          created_at: new Date().toISOString()
        },
        {
          id: '2',
          name: '美食天地',
          description: '美食分享、烹饪技巧、餐厅推荐',
          member_count: 890,
          created_at: new Date().toISOString()
        },
        {
          id: '3',
          name: '旅行日记',
          description: '旅行攻略、景点推荐、游记分享',
          member_count: 2100,
          created_at: new Date().toISOString()
        },
        {
          id: '4',
          name: '科技前沿',
          description: '最新科技资讯、产品评测、技术讨论',
          member_count: 650,
          created_at: new Date().toISOString()
        },
        {
          id: '5',
          name: '读书笔记',
          description: '好书推荐、读书心得、文学交流',
          member_count: 1800,
          created_at: new Date().toISOString()
        }
      ]

      // 根据搜索查询过滤圈子
      const filteredCircles = searchQuery.trim() 
        ? mockCircles.filter(circle => 
            circle.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            circle.description.toLowerCase().includes(searchQuery.toLowerCase())
          )
        : mockCircles

      setAvailableCircles(filteredCircles)
    } catch (error) {
      console.error('获取圈子列表失败:', error)
      toast.error('获取圈子列表失败')
    } finally {
      setIsLoadingCircles(false)
    }
  }

  const handleFollowUser = async (userId: string) => {
    try {
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) {
        toast.error('请先登录')
        return
      }

      if (followedUsers.includes(userId)) {
        // 取消关注
        const { error } = await supabase
          .from('follows')
          .delete()
          .eq('follower_id', user.id)
          .eq('following_id', userId)

        if (error) {
          throw new Error('取消关注失败')
        }

        setFollowedUsers(prev => prev.filter(id => id !== userId))
        toast.success('已取消关注')
      } else {
        // 关注用户
        const { error } = await supabase
          .from('follows')
          .insert({
            follower_id: user.id,
            following_id: userId
          })

        if (error) {
          throw new Error('关注失败')
        }

        setFollowedUsers(prev => [...prev, userId])
        toast.success('关注成功')
      }

      // 刷新帖子列表
      if (activeTab === 'posts') {
        fetchFollowingPosts()
      }
    } catch (error) {
      console.error('操作失败:', error)
      toast.error('操作失败，请稍后重试')
    }
  }

  const handleFollowCircle = async (circleId: string) => {
    try {
      if (followedCircles.includes(circleId)) {
        setFollowedCircles(prev => prev.filter(id => id !== circleId))
        toast.success('已取消关注圈子')
      } else {
        setFollowedCircles(prev => [...prev, circleId])
        toast.success('关注圈子成功')
      }
    } catch (error) {
      console.error('操作失败:', error)
      toast.error('操作失败，请稍后重试')
    }
  }

  useEffect(() => {
    fetchFollowingPosts()
  }, [])

  useEffect(() => {
    if (activeTab === 'users') {
      fetchAvailableUsers()
    } else if (activeTab === 'circles') {
      fetchAvailableCircles()
    }
  }, [activeTab, searchQuery])

  if (isLoading && activeTab === 'posts') {
    return (
      <div className="min-h-screen bg-gradient-to-br from-pink-50 to-blue-50 p-6">
        <div className="max-w-4xl mx-auto">
          <div className="mb-6">
            <h1 className="text-2xl font-bold text-gray-800 mb-2">关注动态</h1>
            <p className="text-gray-600">查看你关注的用户的最新动态</p>
          </div>
          <div className="grid gap-6">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-white rounded-3xl shadow-lg p-6 animate-pulse">
                <div className="flex items-center space-x-3 mb-4">
                  <div className="w-12 h-12 bg-gray-200 rounded-full"></div>
                  <div className="space-y-2">
                    <div className="h-4 bg-gray-200 rounded w-24"></div>
                    <div className="h-3 bg-gray-200 rounded w-16"></div>
                  </div>
                </div>
                <div className="space-y-3">
                  <div className="h-4 bg-gray-200 rounded w-full"></div>
                  <div className="h-4 bg-gray-200 rounded w-3/4"></div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-white to-pink-50 pb-20">
      <div className="max-w-4xl mx-auto p-6">
        <div className="mb-6">
          <h1 className="text-2xl font-bold text-gray-800 mb-2">关注中心</h1>
          <p className="text-gray-600">管理你的关注，发现新内容</p>
        </div>

        {/* 标签页导航 */}
        <div className="mb-6">
          <div className="flex space-x-1 bg-white rounded-2xl p-1 shadow-sm border border-gray-100">
            <button
              onClick={() => setActiveTab('posts')}
              className={`flex-1 py-3 px-4 rounded-xl font-medium transition-all duration-200 ${
                activeTab === 'posts'
                  ? 'bg-gradient-to-r from-pink-500 to-blue-500 text-white shadow-md'
                  : 'text-gray-600 hover:text-gray-800 hover:bg-gray-50'
              }`}
            >
              动态
            </button>
            <button
              onClick={() => setActiveTab('users')}
              className={`flex-1 py-3 px-4 rounded-xl font-medium transition-all duration-200 ${
                activeTab === 'users'
                  ? 'bg-gradient-to-r from-pink-500 to-blue-500 text-white shadow-md'
                  : 'text-gray-600 hover:text-gray-800 hover:bg-gray-50'
              }`}
            >
              用户
            </button>
            <button
              onClick={() => setActiveTab('circles')}
              className={`flex-1 py-3 px-4 rounded-xl font-medium transition-all duration-200 ${
                activeTab === 'circles'
                  ? 'bg-gradient-to-r from-pink-500 to-blue-500 text-white shadow-md'
                  : 'text-gray-600 hover:text-gray-800 hover:bg-gray-50'
              }`}
            >
              圈子
            </button>
          </div>
        </div>

        {/* 搜索栏 */}
        {(activeTab === 'users' || activeTab === 'circles') && (
          <div className="mb-6">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="text"
                placeholder={activeTab === 'users' ? '搜索用户...' : '搜索圈子...'}
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-pink-500 focus:border-transparent bg-white shadow-sm"
              />
            </div>
          </div>
        )}

        {/* 内容区域 */}
        <div className="space-y-6">
          {activeTab === 'posts' && (
            <>
              {posts.length === 0 ? (
                <div className="text-center py-12">
                  <div className="text-6xl mb-4">👥</div>
                  <h3 className="text-xl font-semibold text-gray-600 mb-2">还没有关注动态</h3>
                  <p className="text-gray-500 mb-4">去关注一些用户，查看他们的最新动态吧！</p>
                  <button
                    onClick={() => setActiveTab('users')}
                    className="bg-gradient-to-r from-pink-500 to-blue-500 text-white px-6 py-2 rounded-full font-semibold hover:from-pink-600 hover:to-blue-600 transition-all duration-200"
                  >
                    去发现用户
                  </button>
                </div>
              ) : (
                posts.map((post) => (
                  <PostCard key={post.id} post={post} />
                ))
              )}
            </>
          )}

          {activeTab === 'users' && (
            <>
              {isLoadingUsers ? (
                <div className="grid gap-4">
                  {[1, 2, 3, 4].map((i) => (
                    <div key={i} className="bg-white rounded-2xl shadow-sm p-4 animate-pulse">
                      <div className="flex items-center space-x-3">
                        <div className="w-12 h-12 bg-gray-200 rounded-full"></div>
                        <div className="flex-1 space-y-2">
                          <div className="h-4 bg-gray-200 rounded w-24"></div>
                          <div className="h-3 bg-gray-200 rounded w-32"></div>
                        </div>
                        <div className="w-20 h-8 bg-gray-200 rounded-full"></div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : availableUsers.length === 0 ? (
                <div className="text-center py-12">
                  <Users className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                  <h3 className="text-lg font-semibold text-gray-600 mb-2">没有找到用户</h3>
                  <p className="text-gray-500">试试搜索其他关键词吧</p>
                </div>
              ) : (
                <div className="grid gap-4">
                  {availableUsers.map((user) => (
                    <div key={user.id} className="bg-white rounded-2xl shadow-sm p-4 hover:shadow-md transition-shadow duration-200">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center space-x-3">
                          <img
                            src={user.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(user.username)}&background=random`}
                            alt={user.username}
                            className="w-12 h-12 rounded-full object-cover"
                          />
                          <div>
                            <h4 className="font-semibold text-gray-800">{user.username}</h4>
                            <p className="text-sm text-gray-500">{user.bio || '暂无简介'}</p>
                            <div className="flex items-center space-x-4 text-xs text-gray-400 mt-1">
                              <span>ID: {String(user.id).padStart(10, '0')}</span>
                              <span>{user.followers_count} 粉丝</span>
                              <span>{user.following_count} 关注</span>
                              <span>{user.posts_count} 帖子</span>
                            </div>
                          </div>
                        </div>
                        <button
                          onClick={() => handleFollowUser(user.id)}
                          className={`px-4 py-2 rounded-full font-medium transition-all duration-200 ${
                            followedUsers.includes(user.id)
                              ? 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                              : 'bg-gradient-to-r from-pink-500 to-blue-500 text-white hover:from-pink-600 hover:to-blue-600'
                          }`}
                        >
                          {followedUsers.includes(user.id) ? '已关注' : '关注'}
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </>
          )}

          {activeTab === 'circles' && (
            <>
              {isLoadingCircles ? (
                <div className="grid gap-4">
                  {[1, 2, 3, 4].map((i) => (
                    <div key={i} className="bg-white rounded-2xl shadow-sm p-4 animate-pulse">
                      <div className="flex items-center space-x-3">
                        <div className="w-12 h-12 bg-gray-200 rounded-full"></div>
                        <div className="flex-1 space-y-2">
                          <div className="h-4 bg-gray-200 rounded w-24"></div>
                          <div className="h-3 bg-gray-200 rounded w-32"></div>
                        </div>
                        <div className="w-20 h-8 bg-gray-200 rounded-full"></div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : availableCircles.length === 0 ? (
                <div className="text-center py-12">
                  <Hash className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                  <h3 className="text-lg font-semibold text-gray-600 mb-2">没有找到圈子</h3>
                  <p className="text-gray-500">试试搜索其他关键词吧</p>
                </div>
              ) : (
                <div className="grid gap-4">
                  {availableCircles.map((circle) => (
                    <div key={circle.id} className="bg-white rounded-2xl shadow-sm p-4 hover:shadow-md transition-shadow duration-200">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center space-x-3">
                          <div className="w-12 h-12 bg-gradient-to-br from-pink-400 to-blue-400 rounded-full flex items-center justify-center">
                            <Hash className="w-6 h-6 text-white" />
                          </div>
                          <div>
                            <h4 className="font-semibold text-gray-800">{circle.name}</h4>
                            <p className="text-sm text-gray-500">{circle.description}</p>
                            <div className="flex items-center space-x-4 text-xs text-gray-400 mt-1">
                              <span>{circle.member_count.toLocaleString()} 成员</span>
                            </div>
                          </div>
                        </div>
                        <button
                          onClick={() => handleFollowCircle(circle.id)}
                          className={`px-4 py-2 rounded-full font-medium transition-all duration-200 ${
                            followedCircles.includes(circle.id)
                              ? 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                              : 'bg-gradient-to-r from-pink-500 to-blue-500 text-white hover:from-pink-600 hover:to-blue-600'
                          }`}
                        >
                          {followedCircles.includes(circle.id) ? '已关注' : '关注'}
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  )
}