import { Component, ReactNode } from 'react'

interface Props {
  children: ReactNode
}

interface State {
  hasError: boolean
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false }

  static getDerivedStateFromError(): State {
    return { hasError: true }
  }

  componentDidCatch(error: any, errorInfo: any) {
    console.error('Runtime error caught:', error, errorInfo)
  }

  handleRetry = () => {
    this.setState({ hasError: false })
    window.location.reload()
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-pink-100 to-blue-100">
          <div className="bg-white p-8 rounded-3xl shadow-2xl w-full max-w-md text-center">
            <h1 className="text-2xl font-bold mb-4">页面发生错误</h1>
            <p className="text-gray-600 mb-6">请重试或稍后再试</p>
            <button onClick={this.handleRetry} className="px-6 py-2 bg-pink-500 text-white rounded-xl font-semibold hover:bg-pink-600">
              重新加载
            </button>
          </div>
        </div>
      )
    }
    return this.props.children
  }
}