import { useState, useEffect } from 'react'
import { X, Hash, Save, Loader2 } from 'lucide-react'
import { Post, Tag } from '../types'
import { supabase } from '../lib/supabase'
import { toast } from 'sonner'

interface PostEditModalProps {
  post: Post | null
  isOpen: boolean
  onClose: () => void
  onSave: (updatedPost: Post) => void
}

export function PostEditModal({ post, isOpen, onClose, onSave }: PostEditModalProps) {
  const [content, setContent] = useState('')
  const [tags, setTags] = useState<string[]>([])
  const [tagInput, setTagInput] = useState('')
  const [isLoading, setIsLoading] = useState(false)

  useEffect(() => {
    if (post) {
      setContent(post.content)
      setTags(post.tags.map(tag => tag.name))
    }
  }, [post])

  if (!isOpen || !post) return null

  const handleAddTag = () => {
    if (tagInput.trim() && !tags.includes(tagInput.trim())) {
      setTags([...tags, tagInput.trim()])
      setTagInput('')
    }
  }

  const handleRemoveTag = (tagToRemove: string) => {
    setTags(tags.filter(tag => tag !== tagToRemove))
  }

  const handleSave = async () => {
    if (!content.trim()) {
      toast.error('请输入内容')
      return
    }

    setIsLoading(true)

    try {
      // 更新帖子内容
      const { error: postError } = await supabase
        .from('posts')
        .update({ content: content.trim() })
        .eq('id', post.id)

      if (postError) throw postError

      // 删除现有标签关联
      const { error: deleteTagsError } = await supabase
        .from('post_tags')
        .delete()
        .eq('post_id', post.id)

      if (deleteTagsError) throw deleteTagsError

      // 添加新标签
      for (const tagName of tags) {
        // 获取或创建标签
        const { data: tagData } = await supabase
          .from('tags')
          .select('id')
          .eq('name', tagName)
          .maybeSingle()

        let tagId = tagData?.id

        if (!tagId) {
          const { data: newTag, error: createTagError } = await supabase
            .from('tags')
            .insert([{ name: tagName, category: 'post', usage_count: 0 }])
            .select('id')
            .single()

          if (createTagError) throw createTagError
          tagId = newTag.id
        }

        // 添加帖子标签关联
        const { error: postTagError } = await supabase
          .from('post_tags')
          .insert([{
            post_id: post.id,
            tag_id: tagId
          }])

        if (postTagError) throw postTagError
      }

      // 获取更新后的标签数据
      const { data: updatedTagsData } = await supabase
        .from('post_tags')
        .select('tag:tags(id, name, category, usage_count)')
        .eq('post_id', post.id)

      type PostTagRow = { tag: Tag | Tag[] | null }
      const rows: PostTagRow[] = (updatedTagsData || []) as PostTagRow[]
      const updatedTags: Tag[] = rows
        .map((pt) => Array.isArray(pt.tag) ? pt.tag[0] : pt.tag)
        .filter((t): t is Tag => !!t)

      // 创建更新后的帖子对象
      const updatedPost: Post = {
        ...post,
        content: content.trim(),
        tags: updatedTags
      }

      onSave(updatedPost)
      toast.success('帖子更新成功！')
      onClose()
    } catch (error) {
      console.error('更新帖子失败:', error)
      toast.error('更新帖子失败')
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden">
        {/* 头部 */}
        <div className="flex items-center justify-between p-6 border-b">
          <h2 className="text-xl font-bold text-gray-800">编辑帖子</h2>
          <button
            onClick={onClose}
            className="text-gray-500 hover:text-gray-700 transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* 内容区域 */}
        <div className="p-6 space-y-6">
          {/* 内容输入 */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              内容
            </label>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="w-full p-4 border border-gray-300 rounded-xl focus:ring-2 focus:ring-pink-500 focus:border-pink-500 outline-none resize-none"
              rows={6}
              placeholder="分享你的想法..."
            />
          </div>

          {/* 标签输入 */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              标签
            </label>
            <div className="flex items-center space-x-2 mb-3">
              <Hash className="w-5 h-5 text-gray-400" />
              <input
                type="text"
                value={tagInput}
                onChange={(e) => setTagInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleAddTag()}
                className="flex-1 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-pink-500 focus:border-pink-500 outline-none"
                placeholder="添加标签..."
              />
              <button
                onClick={handleAddTag}
                className="bg-pink-500 text-white px-4 py-2 rounded-lg hover:bg-pink-600 transition-colors"
              >
                添加
              </button>
            </div>

            {/* 标签展示 */}
            {tags.length > 0 && (
              <div className="flex flex-wrap gap-2">
                {tags.map((tag, index) => (
                  <span
                    key={index}
                    className="inline-flex items-center px-3 py-1 bg-pink-100 text-pink-700 rounded-full text-sm"
                  >
                    #{tag}
                    <button
                      onClick={() => handleRemoveTag(tag)}
                      className="ml-2 text-pink-500 hover:text-pink-700"
                    >
                      <X className="w-3 h-3" />
                    </button>
                  </span>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* 底部按钮 */}
        <div className="border-t p-6">
          <div className="flex items-center justify-end space-x-3">
            <button
              onClick={onClose}
              className="px-6 py-2 text-gray-600 hover:text-gray-800 transition-colors"
            >
              取消
            </button>
            <button
              onClick={handleSave}
              disabled={isLoading || !content.trim()}
              className="bg-pink-500 text-white px-6 py-2 rounded-lg hover:bg-pink-600 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center space-x-2"
            >
              {isLoading ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <Save className="w-4 h-4" />
              )}
              <span>{isLoading ? '保存中...' : '保存'}</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}