import { Search, TrendingUp, Sparkles, Tag as TagIcon } from 'lucide-react'
import { useEffect, useState } from 'react'
import { supabase } from '../lib/supabase'
import { useNavigate } from 'react-router-dom'

interface SearchBarProps {
  onSearch?: (query: string) => void
}

export function SearchBar({ onSearch }: SearchBarProps) {
  const [query, setQuery] = useState('')
  const [isFocused, setIsFocused] = useState(false)
  const [tags, setTags] = useState<any[]>([])
  const navigate = useNavigate()

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (query.trim()) {
      const targetTag = tags.find(t => t.name.toLowerCase() === query.trim().toLowerCase())
      if (targetTag) {
        navigate(`/tags/${encodeURIComponent(targetTag.name)}`)
      } else {
        onSearch?.(query.trim())
      }
    }
  }

  const popularSearches = ['动漫', '游戏', 'Cosplay', '插画', '手办', '二次元']

  useEffect(() => {
    ;(async () => {
      const { data } = await supabase
        .from('tags')
        .select('id, name, usage_count, category')
        .order('usage_count', { ascending: false })
        .limit(10)
      setTags(data || [])
    })()
  }, [])

  return (
    <div className="relative">
      <form onSubmit={handleSubmit} className="relative">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 dark:text-gray-500 w-5 h-5" />
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onFocus={() => setIsFocused(true)}
            onBlur={() => setTimeout(() => setIsFocused(false), 200)}
            placeholder="搜索动漫、游戏、Cosplay..."
            className="w-full pl-10 pr-4 py-3 bg-white dark:bg-gray-800 bg-opacity-80 dark:bg-opacity-80 backdrop-blur-sm border border-pink-200 dark:border-gray-600 rounded-full focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none transition-all duration-200 text-gray-800 dark:text-gray-200"
          />
          {query && (
            <button
              type="button"
              onClick={() => setQuery('')}
              className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300"
            >
              ×
            </button>
          )}
        </div>
      </form>

      {/* 搜索建议 */}
      {isFocused && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-gray-800 rounded-2xl shadow-lg border border-pink-100 dark:border-gray-600 p-4 z-50">
          <div className="mb-4">
            <div className="flex items-center space-x-2 mb-3">
              <TagIcon className="w-4 h-4 text-pink-500" />
              <span className="text-sm font-medium text-gray-700 dark:text-gray-200">热门标签</span>
            </div>
            <div className="flex flex-wrap gap-2">
              {tags.map(tag => (
                <button
                  key={tag.id}
                  onClick={() => {
                    setQuery(tag.name)
                    navigate(`/tags/${encodeURIComponent(tag.name)}`)
                  }}
                  className="px-3 py-1 bg-pink-100 dark:bg-pink-900 text-pink-700 dark:text-pink-300 rounded-full text-sm hover:bg-pink-200 dark:hover:bg-pink-800 transition-all duration-200"
                >
                  #{tag.name}
                </button>
              ))}
            </div>
          </div>
          <div className="mb-4">
            <div className="flex items-center space-x-2 mb-3">
              <TrendingUp className="w-4 h-4 text-pink-500" />
              <span className="text-sm font-medium text-gray-700 dark:text-gray-200">热门搜索</span>
            </div>
            <div className="flex flex-wrap gap-2">
              {popularSearches.map((term) => (
                <button
                  key={term}
                  onClick={() => {
                    setQuery(term)
                    onSearch?.(term)
                  }}
                  className="px-3 py-1 bg-pink-100 dark:bg-pink-900 text-pink-700 dark:text-pink-300 rounded-full text-sm hover:bg-pink-200 dark:hover:bg-pink-800 transition-all duration-200"
                >
                  {term}
                </button>
              ))}
            </div>
          </div>
          
          <div className="border-t border-gray-200 dark:border-gray-600 pt-3">
            <div className="flex items-center space-x-2 mb-2">
              <Sparkles className="w-4 h-4 text-blue-500" />
              <span className="text-xs text-gray-500 dark:text-gray-400">搜索发现更多二次元精彩内容</span>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}