import { useState, useEffect } from 'react'
import { Camera, Edit3, Save, X, User, Mail, Calendar, Tag, Image, Clock, Footprints, Plus, Settings as SettingsIcon } from 'lucide-react'
import { supabase } from '../lib/supabase'
import { useAuthStore } from '../stores/authStore'
import { useViewHistoryStore } from '../stores/viewHistoryStore'
import { ViewHistory } from '../components/ViewHistory'
import { Settings } from '../components/Settings'
import { toast } from 'sonner'

interface UserProfile {
  id: string
  username: string
  email: string
  avatar_url: string
  bio: string
  tags: string[]
  background_url: string
  created_at: string
}

export function ProfilePage() {
  const { user } = useAuthStore()
  const { addViewRecord } = useViewHistoryStore()
  const [profile, setProfile] = useState<UserProfile | null>(null)
  const [isEditing, setIsEditing] = useState(false)
  const [editedProfile, setEditedProfile] = useState<UserProfile | null>(null)
  const [isUploading, setIsUploading] = useState(false)
  const [showViewHistory, setShowViewHistory] = useState(false)
  const [showTagModal, setShowTagModal] = useState(false)
  const [showSettings, setShowSettings] = useState(false)
  const [newTagInput, setNewTagInput] = useState('')

  const fetchUserProfile = async () => {
    if (!user) return

    try {
      // 获取用户详细信息
      const { data: userData, error: userError } = await supabase
        .from('users')
        .select('*')
        .eq('id', user.id)
        .single()

      if (userError) throw userError

      // 获取用户标签
      const { data: tagsData, error: tagsError } = await supabase
        .from('user_tags')
        .select('tag:tags(name)')
        .eq('user_id', user.id)

      if (tagsError) throw tagsError

      const tags = tagsData?.map((ut: any) => ut.tag.name) || []

      setProfile({
        id: userData.id,
        username: userData.username,
        email: userData.email,
        avatar_url: userData.avatar_url,
        bio: userData.bio || '',
        tags: tags,
        background_url: userData.background_url || '',
        created_at: userData.created_at
      })
    } catch (error) {
      console.error('获取用户资料失败:', error)
      toast.error('获取用户资料失败')
    }
  }

  useEffect(() => {
    fetchUserProfile()
  }, [user])

  const handleEdit = () => {
    setEditedProfile(profile)
    setIsEditing(true)
  }

  const handleSave = async () => {
    if (!editedProfile || !user) return

    try {
      // 更新用户基本信息
      const { error: updateError } = await supabase
        .from('users')
        .update({
          username: editedProfile.username,
          bio: editedProfile.bio,
          avatar_url: editedProfile.avatar_url,
          background_url: editedProfile.background_url
        })
        .eq('id', user.id)

      if (updateError) throw updateError

      // 更新用户标签
      if (editedProfile.tags !== profile?.tags) {
        // 删除现有标签
        const { error: deleteTagsError } = await supabase
          .from('user_tags')
          .delete()
          .eq('user_id', user.id)

        if (deleteTagsError) throw deleteTagsError

        // 添加新标签
        for (const tagName of editedProfile.tags) {
          // 获取或创建标签
          const { data: tagData, error: tagError } = await supabase
            .from('tags')
            .select('id')
            .eq('name', tagName)
            .single()

          let tagId = tagData?.id

          if (!tagId) {
            const { data: newTag, error: createTagError } = await supabase
              .from('tags')
              .insert([{ name: tagName, category: 'user', usage_count: 0 }])
              .select('id')
              .single()

            if (createTagError) throw createTagError
            tagId = newTag.id
          }

          // 添加用户标签关联
          const { error: userTagError } = await supabase
            .from('user_tags')
            .insert([{
              user_id: user.id,
              tag_id: tagId
            }])

          if (userTagError) throw userTagError
        }
      }

      setProfile(editedProfile)
      setIsEditing(false)
      toast.success('资料更新成功！')
    } catch (error) {
      console.error('更新用户资料失败:', error)
      toast.error('更新用户资料失败')
    }
  }

  const handleCancel = () => {
    setEditedProfile(null)
    setIsEditing(false)
  }

  const handleImageUpload = async (type: 'avatar' | 'background', event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (!file || !user) return

    // 验证文件类型
    const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp', 'image/gif']
    if (!allowedTypes.includes(file.type)) {
      toast.error('请上传图片文件 (JPG, PNG, WebP, GIF)')
      return
    }

    // 验证文件大小 (最大 10MB)
    const maxSize = 10 * 1024 * 1024 // 10MB
    if (file.size > maxSize) {
      toast.error('图片大小不能超过 10MB')
      return
    }

    setIsUploading(true)

    try {
      const fileExt = file.name.split('.').pop()
      const timestamp = Date.now()
      const fileName = `${user.id}-${type}-${timestamp}.${fileExt}`
      const filePath = `${user.id}/${fileName}`

      console.log('开始上传图片:', fileName, '大小:', file.size, '类型:', file.type)

      // 上传图片
      const { error: uploadError } = await supabase.storage
        .from('avatars')
        .upload(filePath, file, {
          cacheControl: '3600',
          upsert: false // 不允许覆盖，确保唯一性
        })

      if (uploadError) {
        console.error('上传错误详情:', uploadError)
        if (uploadError.message.includes('bucket')) {
          throw new Error('存储桶配置错误，请联系管理员')
        } else if (uploadError.message.includes('permission')) {
          throw new Error('权限不足，无法上传图片')
        } else {
          throw uploadError
        }
      }

      console.log('图片上传成功，获取公共URL...')

      // 获取图片URL
      const { data: urlData } = supabase.storage
        .from('avatars')
        .getPublicUrl(filePath)

      if (!urlData?.publicUrl) {
        throw new Error('无法获取图片URL')
      }

      console.log('公共URL获取成功:', urlData.publicUrl)

      // 更新编辑状态
      if (editedProfile) {
        setEditedProfile({
          ...editedProfile,
          [type === 'avatar' ? 'avatar_url' : 'background_url']: urlData.publicUrl
        })
      }

      toast.success(`${type === 'avatar' ? '头像' : '背景图片'}上传成功！`)
    } catch (error) {
      console.error('图片上传失败:', error)
      const errorMessage = error instanceof Error ? error.message : '图片上传失败，请重试'
      toast.error(errorMessage)
    } finally {
      setIsUploading(false)
      // 清空input值，允许重复选择同一文件
      event.target.value = ''
    }
  }

  const addTag = () => {
    if (!editedProfile) return
    setShowTagModal(true)
  }

  const handleAddTag = () => {
    if (!editedProfile || !newTagInput.trim()) return
    
    if (!editedProfile.tags.includes(newTagInput.trim())) {
      setEditedProfile({
        ...editedProfile,
        tags: [...editedProfile.tags, newTagInput.trim()]
      })
    }
    setNewTagInput('')
    setShowTagModal(false)
  }

  const handleCloseTagModal = () => {
    setNewTagInput('')
    setShowTagModal(false)
  }

  const removeTag = (tagToRemove: string) => {
    if (!editedProfile) return
    
    setEditedProfile({
      ...editedProfile,
      tags: editedProfile.tags.filter(tag => tag !== tagToRemove)
    })
  }

  if (!profile) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-pink-50 to-blue-50 p-6">
        <div className="max-w-4xl mx-auto">
          <div className="text-center py-12">
            <div className="text-6xl mb-4">👤</div>
            <h3 className="text-xl font-semibold text-gray-600 mb-2">加载中...</h3>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-white to-pink-50 dark:from-[var(--bg-secondary)] dark:to-[var(--bg-primary)] pb-20 md:pb-0">
      {/* 背景图片 */}
        {profile.background_url && (
          <div className="h-32 md:h-64 relative">
            <img
              src={profile.background_url}
              alt="背景图片"
              className="w-full h-full object-cover"
              onError={(e) => {
                const target = e.target as HTMLImageElement
                target.style.display = 'none'
              }}
            />
            <div className="absolute inset-0 bg-gradient-to-b from-transparent to-white/20"></div>
          </div>
        )}

      <div className="max-w-4xl mx-auto p-3 md:p-6 -mt-16 md:-mt-20 relative z-10">
        {/* 头像和基本信息 */}
        <div className="bg-white rounded-2xl md:rounded-3xl shadow-xl p-4 md:p-8 mb-4 md:mb-6">
          <div className="flex flex-col md:flex-row items-center md:items-start space-y-4 md:space-y-0 md:space-x-8">
            {/* 头像 */}
            <div className="relative">
              <div className="w-24 h-24 md:w-32 md:h-32 rounded-full overflow-hidden border-4 border-white shadow-lg">
                {isEditing ? (
                  editedProfile?.avatar_url ? (
                    <img
                      src={editedProfile.avatar_url}
                      alt="头像"
                      className="w-full h-full object-cover"
                      onError={(e) => {
                        const target = e.target as HTMLImageElement
                        target.style.display = 'none'
                        target.nextElementSibling?.classList.remove('hidden')
                      }}
                    />
                  ) : (
                    <div className="w-full h-full bg-gradient-to-br from-pink-400 to-blue-400 flex items-center justify-center">
                      <User className="w-12 h-12 md:w-16 md:h-16 text-white" />
                    </div>
                  )
                ) : profile.avatar_url ? (
                  <img
                    src={profile.avatar_url}
                    alt="头像"
                    className="w-full h-full object-cover"
                    onError={(e) => {
                      const target = e.target as HTMLImageElement
                      target.style.display = 'none'
                      target.nextElementSibling?.classList.remove('hidden')
                    }}
                  />
                ) : (
                  <div className="w-full h-full bg-gradient-to-br from-pink-400 to-blue-400 flex items-center justify-center">
                    <User className="w-12 h-12 md:w-16 md:h-16 text-white" />
                  </div>
                )}
                {/* 头像加载失败时的备用显示 */}
                <div className="hidden w-full h-full bg-gradient-to-br from-pink-400 to-blue-400 flex items-center justify-center">
                  <User className="w-12 h-12 md:w-16 md:h-16 text-white" />
                </div>
              </div>
              
              {isEditing && (
                <label className="absolute -bottom-1 -right-1 md:-bottom-2 md:-right-2 bg-pink-500 text-white p-1.5 md:p-2 rounded-full cursor-pointer hover:bg-pink-600 transition-colors shadow-lg">
                  <Camera className="w-3 h-3 md:w-4 md:h-4" />
                  <input
                    type="file"
                    accept="image/*"
                    className="hidden"
                    onChange={(e) => handleImageUpload('avatar', e)}
                    disabled={isUploading}
                  />
                </label>
              )}
            </div>

            {/* 基本信息 */}
            <div className="flex-1 text-center md:text-left space-y-3 md:space-y-4">
              {isEditing ? (
                <div className="space-y-3 md:space-y-4">
                  <input
                    type="text"
                    value={editedProfile?.username || ''}
                    onChange={(e) => setEditedProfile(prev => prev ? { ...prev, username: e.target.value } : null)}
                    className="text-xl md:text-2xl font-bold bg-transparent border-b-2 border-pink-300 focus:border-pink-500 outline-none pb-1 text-center md:text-left"
                    placeholder="用户名"
                  />
                  <textarea
                    value={editedProfile?.bio || ''}
                    onChange={(e) => setEditedProfile(prev => prev ? { ...prev, bio: e.target.value } : null)}
                    className="w-full p-2 md:p-3 border border-gray-300 rounded-lg focus:border-pink-500 outline-none resize-none text-sm md:text-base"
                    rows={3}
                    placeholder="个人简介"
                  />
                </div>
              ) : (
                <div className="space-y-2 md:space-y-4">
                  <h1 className="text-2xl md:text-3xl font-bold text-gray-800 mb-1 md:mb-2">{profile.username}</h1>
                  <p className="text-gray-600 mb-3 md:mb-4 text-sm md:text-base">{profile.bio || '这个人很懒，什么都没有写...'}</p>
                  <div className="flex flex-wrap items-center justify-center md:justify-start gap-3 md:gap-4 text-xs md:text-sm text-gray-500">
                    <div className="flex items-center space-x-1">
                      <Mail className="w-3 h-3 md:w-4 md:h-4" />
                      <span className="truncate">{profile.email}</span>
                    </div>
                    <div className="flex items-center space-x-1">
                      <Calendar className="w-3 h-3 md:w-4 md:h-4" />
                      <span>加入于 {new Date(profile.created_at).toLocaleDateString()}</span>
                    </div>
                    <div className="flex items-center space-x-1">
                      <User className="w-3 h-3 md:w-4 md:h-4" />
                      <span>ID: {String(profile.id).substring(0, 8)}</span>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* 编辑按钮 */}
            <div className="flex space-x-2 md:space-x-3">
              {!isEditing && (
                <button
                  onClick={() => setShowSettings(true)}
                  className="bg-gray-500 text-white px-3 md:px-4 py-2 rounded-lg hover:bg-gray-600 transition-colors flex items-center space-x-1 md:space-x-2 text-sm md:text-base"
                >
                  <SettingsIcon className="w-3 h-3 md:w-4 md:h-4" />
                  <span>设置</span>
                </button>
              )}
              {isEditing ? (
                <>
                  <button
                    onClick={handleSave}
                    className="bg-pink-500 text-white px-3 md:px-4 py-2 rounded-lg hover:bg-pink-600 transition-colors flex items-center space-x-1 md:space-x-2 text-sm md:text-base"
                    disabled={isUploading}
                  >
                    <Save className="w-3 h-3 md:w-4 md:h-4" />
                    <span>{isUploading ? '保存中...' : '保存'}</span>
                  </button>
                  <button
                    onClick={handleCancel}
                    className="bg-gray-300 text-gray-700 px-3 md:px-4 py-2 rounded-lg hover:bg-gray-400 transition-colors flex items-center space-x-1 md:space-x-2 text-sm md:text-base"
                    disabled={isUploading}
                  >
                    <X className="w-3 h-3 md:w-4 md:h-4" />
                    <span>取消</span>
                  </button>
                </>
              ) : (
                <button
                  onClick={handleEdit}
                  className="bg-pink-500 text-white px-3 md:px-4 py-2 rounded-lg hover:bg-pink-600 transition-colors flex items-center space-x-1 md:space-x-2 text-sm md:text-base"
                >
                  <Edit3 className="w-3 h-3 md:w-4 md:h-4" />
                  <span>编辑资料</span>
                </button>
              )}
            </div>
          </div>
        </div>

        {/* 标签 */}
        <div className="bg-white rounded-3xl shadow-xl p-8 mb-6">
          <h3 className="text-xl font-bold text-gray-800 mb-4 flex items-center space-x-2">
            <Tag className="w-5 h-5" />
            <span>个人标签</span>
          </h3>
          
          {isEditing ? (
            <div className="space-y-4">
              <div className="flex flex-wrap gap-2">
                {editedProfile?.tags.map((tag, index) => (
                  <span
                    key={index}
                    className="inline-flex items-center px-3 py-1 bg-pink-100 text-pink-700 rounded-full text-sm"
                  >
                    {tag}
                    <button
                      onClick={() => removeTag(tag)}
                      className="ml-2 text-pink-500 hover:text-pink-700"
                    >
                      <X className="w-3 h-3" />
                    </button>
                  </span>
                ))}
              </div>
              <button
                onClick={addTag}
                className="bg-pink-500 text-white px-4 py-2 rounded-lg hover:bg-pink-600 transition-colors"
              >
                添加标签
              </button>
            </div>
          ) : (
            <div className="flex flex-wrap gap-2">
              {profile.tags.length > 0 ? (
                profile.tags.map((tag, index) => (
                  <span
                    key={index}
                    className="inline-block px-3 py-1 bg-pink-100 text-pink-700 rounded-full text-sm"
                  >
                    #{tag}
                  </span>
                ))
              ) : (
                <p className="text-gray-500">暂无标签</p>
              )}
            </div>
          )}
        </div>

        {/* 背景图片编辑 */}
        {isEditing && (
          <div className="bg-white rounded-3xl shadow-xl p-8">
            <h3 className="text-xl font-bold text-gray-800 mb-4 flex items-center space-x-2">
              <Image className="w-5 h-5" />
              <span>背景图片</span>
            </h3>
            
            <div className="space-y-4">
              {editedProfile?.background_url && (
                <img
                  src={editedProfile.background_url}
                  alt="背景图片"
                  className="w-full h-32 object-cover rounded-lg"
                />
              )}
              <label className="bg-pink-500 text-white px-4 py-2 rounded-lg hover:bg-pink-600 transition-colors cursor-pointer inline-block">
                上传背景图片
                <input
                  type="file"
                  accept="image/*"
                  className="hidden"
                  onChange={(e) => handleImageUpload('background', e)}
                  disabled={isUploading}
                />
              </label>
            </div>
          </div>
        )}

        {/* 浏览记录 */}
        {!isEditing && (
          <div className="bg-white rounded-3xl shadow-xl p-8">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-xl font-bold text-gray-800 flex items-center space-x-2">
                <Footprints className="w-5 h-5" />
                <span>我的足迹</span>
              </h3>
              <button
                onClick={() => setShowViewHistory(!showViewHistory)}
                className="text-pink-500 hover:text-pink-600 transition-colors flex items-center space-x-1"
              >
                <Clock className="w-4 h-4" />
                <span>{showViewHistory ? '收起' : '查看全部'}</span>
              </button>
            </div>
            
            {showViewHistory ? (
              <ViewHistory onClose={() => setShowViewHistory(false)} />
            ) : (
              <div className="space-y-3">
                <p className="text-gray-600 text-sm">最近浏览的内容会显示在这里</p>
                <button
                  onClick={() => setShowViewHistory(true)}
                  className="w-full bg-gradient-to-r from-pink-500 to-blue-500 text-white py-3 rounded-xl font-medium hover:from-pink-600 hover:to-blue-600 transition-all duration-200"
                >
                  查看浏览记录
                </button>
              </div>
            )}
          </div>
        )}
      </div>

      {/* 添加标签模态框 */}
      {showTagModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-[var(--bg-card)] rounded-2xl p-6 w-full max-w-sm mx-4">
            <h3 className="text-lg font-semibold text-gray-800 dark:text-white mb-4">添加标签</h3>
            <input
              type="text"
              value={newTagInput}
              onChange={(e) => setNewTagInput(e.target.value)}
              placeholder="请输入标签名称"
              className="w-full px-4 py-3 border border-gray-300 dark:border-[var(--border-color)] bg-white dark:bg-[var(--bg-secondary)] text-gray-800 dark:text-white rounded-lg focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none mb-4"
              onKeyPress={(e) => e.key === 'Enter' && handleAddTag()}
              autoFocus
            />
            <div className="flex space-x-3">
              <button
                onClick={handleCloseTagModal}
                className="flex-1 px-4 py-2 border border-gray-300 dark:border-[var(--border-color)] text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
              >
                取消
              </button>
              <button
                onClick={handleAddTag}
                className="flex-1 px-4 py-2 bg-pink-500 text-white rounded-lg hover:bg-pink-600 transition-colors"
              >
                添加
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 设置模态框 */}
      {showSettings && (
        <Settings onClose={() => setShowSettings(false)} />
      )}
    </div>
  )
}