import { useEffect, useState } from 'react'
import { useParams } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { toast } from 'sonner'
import { PostCard } from '../components/PostCard'

type SortType = 'latest' | 'hot'

export function TagDetailPage() {
  const { name } = useParams()
  const [sort, setSort] = useState<SortType>('latest')
  const [isLoading, setIsLoading] = useState(true)
  const [posts, setPosts] = useState<any[]>([])
  const [tag, setTag] = useState<any>(null)

  const fetchData = async () => {
    try {
      setIsLoading(true)
      const { data: tagData, error: tagError } = await supabase
        .from('tags')
        .select('*')
        .eq('name', name)
        .single()
      if (tagError || !tagData) {
        toast.error('未找到该标签')
        setPosts([])
        return
      }
      setTag(tagData)

      const { data: ptData, error: ptError } = await supabase
        .from('post_tags')
        .select('post_id')
        .eq('tag_id', tagData.id)
      if (ptError) throw ptError

      const postIds = (ptData || []).map((p: any) => p.post_id)
      if (postIds.length === 0) {
        setPosts([])
        return
      }

      let query = supabase.from('posts').select('*').in('id', postIds)
      query = sort === 'latest' ? query.order('created_at', { ascending: false }) : query.order('likes_count', { ascending: false })
      const { data: postsData, error: postsError } = await query
      if (postsError) throw postsError

      const { data: { user } } = await supabase.auth.getUser()

      const withDetails = await Promise.all(
        (postsData || []).map(async (post: any) => {
          const { data: userData } = await supabase
            .from('users')
            .select('id, username, avatar_url')
            .eq('id', post.user_id)
            .single()
          const { data: tagRows } = await supabase
            .from('post_tags')
            .select('tag:tags(id, name, category, usage_count)')
            .eq('post_id', post.id)

          let is_liked = false
          let is_favorited = false
          if (user) {
            const { data: likeData } = await supabase
              .from('likes')
              .select('id')
              .eq('user_id', user.id)
              .eq('post_id', post.id)
              .maybeSingle()
            is_liked = !!likeData
            const { data: favData } = await supabase
              .from('favorites')
              .select('id')
              .eq('user_id', user.id)
              .eq('post_id', post.id)
              .maybeSingle()
            is_favorited = !!favData
          }

          return {
            ...post,
            user: userData || { id: post.user_id, username: '未知用户', avatar_url: null },
            tags: (tagRows || []).map((t: any) => t.tag),
            is_liked,
            is_favorited,
            images: Array.isArray(post.images) ? post.images : [],
            videos: Array.isArray(post.videos) ? post.videos : [],
            comments_count: post.comments_count || 0,
            likes_count: post.likes_count || 0
          }
        })
      )

      setPosts(withDetails)
    } catch (e: any) {
      toast.error(e.message || '加载标签内容失败')
      setPosts([])
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    fetchData()
  }, [name, sort])

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-white to-pink-50 p-6">
        <div className="max-w-4xl mx-auto">
          <div className="grid gap-6">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-white rounded-3xl shadow-lg p-6 animate-pulse"></div>
            ))}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-white to-pink-50 pb-20 md:pb-0">
      <main className="max-w-4xl mx-auto p-6">
        <div className="mb-6 flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-800">#{name}</h1>
            {tag && <p className="text-gray-500 text-sm">共 {posts.length} 条内容</p>}
          </div>
          <div className="flex space-x-2">
            <button
              onClick={() => setSort('latest')}
              className={`px-4 py-2 rounded-full font-medium ${sort === 'latest' ? 'bg-pink-500 text-white' : 'bg-pink-100 text-pink-700 hover:bg-pink-200'}`}
            >最新</button>
            <button
              onClick={() => setSort('hot')}
              className={`px-4 py-2 rounded-full font-medium ${sort === 'hot' ? 'bg-pink-500 text-white' : 'bg-pink-100 text-pink-700 hover:bg-pink-200'}`}
            >最热门</button>
          </div>
        </div>

        <div className="space-y-6">
          {posts.length === 0 ? (
            <div className="text-center py-12">
              <div className="text-6xl mb-4">🏷️</div>
              <h3 className="text-xl font-semibold text-gray-600 mb-2">这个标签还没有内容</h3>
              <p className="text-gray-500">去成为第一个分享的人吧！</p>
            </div>
          ) : (
            posts.map((post) => (
              <PostCard key={post.id} post={post} />
            ))
          )}
        </div>
      </main>
    </div>
  )
}