import { useEffect, useState } from 'react'
import { useParams } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { toast } from 'sonner'
import { PostCard } from '../components/PostCard'
import { Tag as TagIcon } from 'lucide-react'

export function UserProfilePage() {
  const { id } = useParams()
  const [userInfo, setUserInfo] = useState<any>(null)
  const [tags, setTags] = useState<any[]>([])
  const [posts, setPosts] = useState<any[]>([])
  const [isLoading, setIsLoading] = useState(true)

  const fetchAll = async () => {
    try {
      setIsLoading(true)
      const { data: uData, error: uErr } = await supabase
        .from('users')
        .select('*')
        .eq('id', id)
        .single()
      if (uErr || !uData) {
        toast.error('未找到该用户')
        return
      }
      setUserInfo(uData)

      const { data: utRows } = await supabase
        .from('user_tags')
        .select('tag:tags(id, name, category)')
        .eq('user_id', id)
      setTags((utRows || []).map((r: any) => r.tag))

      const { data: postsData, error: pErr } = await supabase
        .from('posts')
        .select('*')
        .eq('user_id', id)
        .order('created_at', { ascending: false })
        .limit(20)
      if (pErr) throw pErr

      const withDetails = await Promise.all(
        (postsData || []).map(async (post: any) => {
          const { data: userData } = await supabase
            .from('users')
            .select('id, username, avatar_url')
            .eq('id', post.user_id)
            .single()
          const { data: tagRows } = await supabase
            .from('post_tags')
            .select('tag:tags(id, name, category, usage_count)')
            .eq('post_id', post.id)

          return {
            ...post,
            user: userData || { id: post.user_id, username: '未知用户', avatar_url: null },
            tags: (tagRows || []).map((t: any) => t.tag),
            is_liked: false,
            is_favorited: false,
            images: Array.isArray(post.images) ? post.images : [],
            videos: Array.isArray(post.videos) ? post.videos : [],
            comments_count: post.comments_count || 0,
            likes_count: post.likes_count || 0
          }
        })
      )

      setPosts(withDetails)
    } catch (e: any) {
      toast.error(e.message || '加载用户信息失败')
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    fetchAll()
  }, [id])

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-white to-pink-50 p-6"></div>
    )
  }

  if (!userInfo) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-white to-pink-50 p-6">
        <div className="max-w-4xl mx-auto text-center text-gray-600">未找到该用户</div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-white to-pink-50 pb-20 md:pb-0">
      <div className="h-40 md:h-56 bg-pink-100"></div>
      <main className="max-w-4xl mx-auto p-6 -mt-16">
        <div className="bg-white rounded-3xl shadow-xl p-8 mb-6">
          <div className="flex items-center space-x-4">
            <img
              src={userInfo.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${userInfo.username}`}
              alt={userInfo.username}
              className="w-20 h-20 rounded-full object-cover border-4 border-white shadow"
            />
            <div>
              <h1 className="text-2xl font-bold text-gray-800">{userInfo.username}</h1>
              <p className="text-gray-600 text-sm">{userInfo.bio || '这个人很神秘'}</p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-3xl shadow-xl p-8 mb-6">
          <h3 className="text-xl font-bold text-gray-800 mb-4 flex items-center space-x-2">
            <TagIcon className="w-5 h-5" />
            <span>所属圈子</span>
          </h3>
          <div className="flex flex-wrap gap-2">
            {tags.length > 0 ? (
              tags.map((t) => (
                <a
                  key={t.id}
                  href={`/tags/${encodeURIComponent(t.name)}`}
                  className="px-3 py-1 bg-pink-100 text-pink-700 rounded-full text-sm hover:bg-pink-200"
                >
                  #{t.name}
                </a>
              ))
            ) : (
              <span className="text-gray-500">暂无圈子</span>
            )}
          </div>
        </div>

        <div className="space-y-6">
          {posts.length === 0 ? (
            <div className="text-center py-12 text-gray-600">TA 还没有发布内容</div>
          ) : (
            posts.map((p) => <PostCard key={p.id} post={p} />)
          )}
        </div>
      </main>
    </div>
  )
}