import { create } from 'zustand'
import { persist } from 'zustand/middleware'

interface ViewRecord {
  id: string
  postId: string
  postTitle?: string
  postContent?: string
  postImage?: string
  authorName?: string
  authorAvatar?: string
  timestamp: number
}

interface ViewHistoryState {
  viewHistory: ViewRecord[]
  maxRecords: number
  addViewRecord: (record: Omit<ViewRecord, 'id' | 'timestamp'>) => void
  clearViewHistory: () => void
  removeViewRecord: (id: string) => void
  getRecentViews: (limit?: number) => ViewRecord[]
}

export const useViewHistoryStore = create<ViewHistoryState>()(
  persist(
    (set, get) => ({
      viewHistory: [],
      maxRecords: 100, // 最多保存100条浏览记录
      
      addViewRecord: (record) => {
        const newRecord: ViewRecord = {
          ...record,
          id: `${record.postId}-${Date.now()}`,
          timestamp: Date.now()
        }
        
        set((state) => {
          // 移除已存在的相同帖子记录
          const filteredHistory = state.viewHistory.filter(
            item => item.postId !== record.postId
          )
          
          // 添加新记录到开头
          const newHistory = [newRecord, ...filteredHistory]
          
          // 限制记录数量
          if (newHistory.length > state.maxRecords) {
            newHistory.pop()
          }
          
          return { viewHistory: newHistory }
        })
      },
      
      clearViewHistory: () => {
        set({ viewHistory: [] })
      },
      
      removeViewRecord: (id) => {
        set((state) => ({
          viewHistory: state.viewHistory.filter(item => item.id !== id)
        }))
      },
      
      getRecentViews: (limit = 20) => {
        const state = get()
        return state.viewHistory.slice(0, limit)
      }
    }),
    {
      name: 'view-history-storage',
      partialize: (state) => ({
        viewHistory: state.viewHistory,
        maxRecords: state.maxRecords
      })
    }
  )
)