import { useState } from 'react'
import { Heart, MessageCircle, Bookmark, Share2, X } from 'lucide-react'
import { Post } from '../types'
import { supabase } from '../lib/supabase'
import { toast } from 'sonner'
import { CommentSection } from './CommentSection'

interface PostDetailModalProps {
  post: Post
  isOpen: boolean
  onClose: () => void
}

export function PostDetailModal({ post, isOpen, onClose }: PostDetailModalProps) {
  const [isLiked, setIsLiked] = useState(post.is_liked)
  const [isFavorited, setIsFavorited] = useState(post.is_favorited)
  const [likesCount, setLikesCount] = useState(post.likes_count)
  const [comments, setComments] = useState(post.comments || [])
  const [isLoading, setIsLoading] = useState(false)

  if (!isOpen) return null

  const handleLike = async () => {
    try {
      setIsLoading(true)
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) {
        toast.error('请先登录')
        return
      }

      if (isLiked) {
        const { error } = await supabase
          .from('likes')
          .delete()
          .eq('user_id', user.id)
          .eq('post_id', post.id)
        
        if (error) throw error
        setIsLiked(false)
        setLikesCount(prev => prev - 1)
        toast.success('取消点赞')
      } else {
        const { error } = await supabase
          .from('likes')
          .insert({
            user_id: user.id,
            post_id: post.id
          })
        
        if (error) throw error
        setIsLiked(true)
        setLikesCount(prev => prev + 1)
        toast.success('点赞成功')
      }
    } catch (error) {
      toast.error('操作失败')
    } finally {
      setIsLoading(false)
    }
  }

  const handleFavorite = async () => {
    try {
      setIsLoading(true)
      if (isFavorited) {
        // 取消收藏逻辑
        setIsFavorited(false)
        toast.success('取消收藏')
      } else {
        // 收藏逻辑
        setIsFavorited(true)
        toast.success('收藏成功')
      }
    } catch (error) {
      toast.error('操作失败')
    } finally {
      setIsLoading(false)
    }
  }

  const handleCommentAdded = (newComment: any) => {
    setComments(prev => [...prev, newComment])
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden">
        {/* 头部 */}
        <div className="flex items-center justify-between p-6 border-b">
          <div className="flex items-center space-x-3">
            <img
              src={post.user.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${post.user.username}`}
              alt={post.user.username}
              className="w-10 h-10 rounded-full object-cover"
            />
            <div>
              <h3 className="font-semibold text-gray-800">{post.user.username}</h3>
              <p className="text-sm text-gray-500">
                {new Date(post.created_at).toLocaleDateString('zh-CN')}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-gray-500 hover:text-gray-700 transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex max-h-[calc(90vh-140px)]">
          {/* 左侧图片 */}
          <div className="w-1/2 bg-gray-100 flex items-center justify-center">
            {post.images.length > 0 ? (
              <div className="grid grid-cols-1 gap-2 p-4 w-full">
                {post.images.map((image, index) => (
                  <div key={index} className="aspect-square rounded-xl overflow-hidden">
                    <img
                      src={image}
                      alt={`图片 ${index + 1}`}
                      className="w-full h-full object-cover"
                    />
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center text-gray-400">
                <div className="text-6xl mb-4">🖼️</div>
                <p>暂无图片</p>
              </div>
            )}
          </div>

          {/* 右侧内容 */}
          <div className="w-1/2 flex flex-col">
            {/* 内容区域 */}
            <div className="flex-1 p-6 overflow-y-auto">
              <div className="mb-6">
                <p className="text-gray-800 text-lg leading-relaxed">{post.content}</p>
                
                {/* 标签 */}
                {post.tags.length > 0 && (
                  <div className="flex flex-wrap gap-2 mt-4">
                    {post.tags.map((tag) => (
                      <span
                        key={tag.id}
                        className="px-3 py-1 bg-gradient-to-r from-pink-100 to-blue-100 text-pink-700 rounded-full text-sm font-medium"
                      >
                        #{tag.name}
                      </span>
                    ))}
                  </div>
                )}
              </div>

              {/* 互动统计 */}
              <div className="flex items-center space-x-6 text-sm text-gray-500 mb-6">
                <span>{likesCount} 个赞</span>
                <span>{comments.length} 条评论</span>
              </div>

              {/* 评论区域 */}
              <CommentSection
                postId={post.id}
                onCommentAdded={handleCommentAdded}
              />
            </div>

            {/* 底部互动按钮 */}
            <div className="border-t p-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-6">
                  <button
                    onClick={handleLike}
                    disabled={isLoading}
                    className={`flex items-center space-x-2 transition-colors ${
                      isLiked ? 'text-red-500' : 'text-gray-500 hover:text-red-500'
                    }`}
                  >
                    <Heart className={`w-5 h-5 ${isLiked ? 'fill-current' : ''}`} />
                    <span className="text-sm font-medium">{likesCount}</span>
                  </button>
                  
                  <button className="flex items-center space-x-2 text-gray-500 hover:text-blue-500 transition-colors">
                    <MessageCircle className="w-5 h-5" />
                    <span className="text-sm font-medium">{comments.length}</span>
                  </button>
                  
                  <button
                    onClick={handleFavorite}
                    disabled={isLoading}
                    className={`transition-colors ${
                      isFavorited ? 'text-yellow-500' : 'text-gray-500 hover:text-yellow-500'
                    }`}
                  >
                    <Bookmark className={`w-5 h-5 ${isFavorited ? 'fill-current' : ''}`} />
                  </button>
                </div>
                
                <button className="text-gray-500 hover:text-green-500 transition-colors">
                  <Share2 className="w-5 h-5" />
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}