import { useState, useEffect } from 'react'
import { Send, Heart, MessageCircle, MoreVertical, Trash2, Edit3, X } from 'lucide-react'
import { supabase } from '../lib/supabase'
import { useAuthStore } from '../stores/authStore'
import { toast } from 'sonner'

interface Comment {
  id: string
  content: string
  created_at: string
  user_id: string
  post_id: string
  user: {
    id: string
    username: string
    avatar_url: string
    sequential_id: string
  }
  likes_count: number
  is_liked: boolean
}

interface CommentSectionProps {
  postId: string
  onCommentAdded?: (newComment: Comment) => void
}

export function CommentSection({ postId, onCommentAdded }: CommentSectionProps) {
  const { user } = useAuthStore()
  const [comments, setComments] = useState<Comment[]>([])
  const [newComment, setNewComment] = useState('')
  const [isLoading, setIsLoading] = useState(true)
  const [editingComment, setEditingComment] = useState<string | null>(null)
  const [editContent, setEditContent] = useState('')

  const fetchComments = async () => {
    try {
      const { data, error } = await supabase
        .from('comments')
        .select(`
          *,
          user:users!user_id(
            id,
            username,
            avatar_url,
            sequential_id
          )
        `)
        .eq('post_id', postId)
        .order('created_at', { ascending: false })

      if (error) throw error

      // 检查每条评论的点赞状态
      const commentsWithLikes = await Promise.all(
        (data || []).map(async (comment) => {
          let is_liked = false
          let likes_count = 0

          if (user) {
            // 检查是否点赞
            const { data: likeData } = await supabase
              .from('comment_likes')
              .select('id')
              .eq('user_id', user.id)
              .eq('comment_id', comment.id)
              .maybeSingle()

            is_liked = !!likeData
          }

          // 获取点赞数
          const { count } = await supabase
            .from('comment_likes')
            .select('*', { count: 'exact', head: true })
            .eq('comment_id', comment.id)

          likes_count = count || 0

          return {
            ...comment,
            is_liked,
            likes_count
          }
        })
      )

      setComments(commentsWithLikes)
    } catch (error) {
      console.error('获取评论失败:', error)
      toast.error('获取评论失败')
    } finally {
      setIsLoading(false)
    }
  }

  const handleSubmitComment = async () => {
    if (!user || !newComment.trim()) return

    try {
      const { data, error } = await supabase
        .from('comments')
        .insert({
          post_id: postId,
          user_id: user.id,
          content: newComment.trim()
        })
        .select(`
          *,
          user:users!user_id(
            id,
            username,
            avatar_url,
            sequential_id
          )
        `)
        .single()

      if (error) throw error

      setComments([data, ...comments])
      setNewComment('')
      toast.success('评论发布成功')

      // 调用回调函数通知父组件
      onCommentAdded?.(data)

      // 更新帖子评论数
      await supabase
        .from('posts')
        .update({ comments_count: comments.length + 1 })
        .eq('id', postId)

    } catch (error) {
      console.error('发布评论失败:', error)
      toast.error('发布评论失败')
    }
  }

  const handleLikeComment = async (commentId: string) => {
    if (!user) {
      toast.error('请先登录')
      return
    }

    try {
      const comment = comments.find(c => c.id === commentId)
      if (!comment) return

      if (comment.is_liked) {
        // 取消点赞
        await supabase
          .from('comment_likes')
          .delete()
          .eq('user_id', user.id)
          .eq('comment_id', commentId)

        setComments(comments.map(c => 
          c.id === commentId 
            ? { ...c, is_liked: false, likes_count: Math.max(0, c.likes_count - 1) }
            : c
        ))
      } else {
        // 点赞
        await supabase
          .from('comment_likes')
          .insert({
            user_id: user.id,
            comment_id: commentId
          })

        setComments(comments.map(c => 
          c.id === commentId 
            ? { ...c, is_liked: true, likes_count: c.likes_count + 1 }
            : c
        ))
      }
    } catch (error) {
      console.error('点赞评论失败:', error)
      toast.error('点赞评论失败')
    }
  }

  const handleDeleteComment = async (commentId: string) => {
    if (!user) return

    if (window.confirm('确定要删除这条评论吗？')) {
      try {
        const { error } = await supabase
          .from('comments')
          .delete()
          .eq('id', commentId)
          .eq('user_id', user.id)

        if (error) throw error

        setComments(comments.filter(c => c.id !== commentId))
        toast.success('评论删除成功')

        // 更新帖子评论数
        await supabase
          .from('posts')
          .update({ comments_count: Math.max(0, comments.length - 1) })
          .eq('id', postId)

      } catch (error) {
        console.error('删除评论失败:', error)
        toast.error('删除评论失败')
      }
    }
  }

  const handleEditComment = async (commentId: string) => {
    if (!user || !editContent.trim()) return

    try {
      const { error } = await supabase
        .from('comments')
        .update({ content: editContent.trim() })
        .eq('id', commentId)
        .eq('user_id', user.id)

      if (error) throw error

      setComments(comments.map(c => 
        c.id === commentId 
          ? { ...c, content: editContent.trim() }
          : c
      ))
      
      setEditingComment(null)
      setEditContent('')
      toast.success('评论编辑成功')

    } catch (error) {
      console.error('编辑评论失败:', error)
      toast.error('编辑评论失败')
    }
  }

  useEffect(() => {
    fetchComments()
  }, [postId, user])

  if (isLoading) {
    return (
      <div className="space-y-4">
        {[1, 2, 3].map((i) => (
          <div key={i} className="bg-gray-50 dark:bg-gray-900 rounded-lg p-4 animate-pulse">
            <div className="flex items-start space-x-3">
              <div className="w-8 h-8 bg-gray-200 dark:bg-gray-700 rounded-full"></div>
              <div className="flex-1 space-y-2">
                <div className="h-3 bg-gray-200 dark:bg-gray-700 rounded w-20"></div>
                <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-full"></div>
                <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-3/4"></div>
              </div>
            </div>
          </div>
        ))}
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* 评论输入框 */}
      {user && (
        <div className="bg-gray-50 dark:bg-gray-900 rounded-lg p-4">
          <div className="flex items-start space-x-3">
            <img
              src={user.user_metadata?.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(user.email || '用户')}&background=random`}
              alt="我的头像"
              className="w-8 h-8 rounded-full object-cover"
            />
            <div className="flex-1">
              <textarea
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                placeholder="写下你的评论..."
                className="w-full p-3 border border-gray-300 dark:border-gray-600 rounded-lg resize-none focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none bg-white dark:bg-gray-800 text-gray-800 dark:text-white"
                rows={3}
              />
              <div className="flex justify-end mt-2">
                <button
                  onClick={handleSubmitComment}
                  disabled={!newComment.trim()}
                  className="bg-pink-500 text-white px-4 py-2 rounded-lg hover:bg-pink-600 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center space-x-2"
                >
                  <Send className="w-4 h-4" />
                  <span>发布</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 评论列表 */}
      <div className="space-y-4">
        {comments.length === 0 ? (
          <div className="text-center py-8">
            <MessageCircle className="w-12 h-12 text-gray-400 mx-auto mb-4" />
            <p className="text-gray-500 dark:text-gray-400">
              {user ? '还没有评论，来抢沙发吧！' : '登录后可以评论'}
            </p>
          </div>
        ) : (
          comments.map((comment) => (
            <div key={comment.id} className="bg-gray-50 dark:bg-gray-900 rounded-lg p-4">
              <div className="flex items-start space-x-3">
                <img
                  src={comment.user.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(comment.user.username)}&background=random`}
                  alt={comment.user.username}
                  className="w-8 h-8 rounded-full object-cover"
                />
                <div className="flex-1">
                  <div className="flex items-center justify-between mb-2">
                    <div className="flex items-center space-x-2">
                      <span className="font-medium text-gray-800 dark:text-white">
                        {comment.user.username}
                      </span>
                      <span className="text-xs text-gray-500 dark:text-gray-400">
                        ID: {comment.user.sequential_id}
                      </span>
                    </div>
                    <div className="flex items-center space-x-2">
                      <span className="text-xs text-gray-500 dark:text-gray-400">
                        {new Date(comment.created_at).toLocaleString()}
                      </span>
                      {user && comment.user_id === user.id && (
                        <div className="relative">
                          <button
                            onClick={() => {
                              if (editingComment === comment.id) {
                                setEditingComment(null)
                                setEditContent('')
                              } else {
                                setEditingComment(comment.id)
                                setEditContent(comment.content)
                              }
                            }}
                            className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded transition-colors"
                          >
                            {editingComment === comment.id ? (
                              <X className="w-4 h-4" />
                            ) : (
                              <Edit3 className="w-4 h-4" />
                            )}
                          </button>
                        </div>
                      )}
                    </div>
                  </div>

                  {editingComment === comment.id ? (
                    <div className="space-y-2">
                      <textarea
                        value={editContent}
                        onChange={(e) => setEditContent(e.target.value)}
                        className="w-full p-2 border border-gray-300 dark:border-gray-600 rounded-lg resize-none focus:ring-2 focus:ring-pink-500 focus:border-transparent outline-none bg-white dark:bg-gray-800 text-gray-800 dark:text-white"
                        rows={2}
                      />
                      <div className="flex justify-end space-x-2">
                        <button
                          onClick={() => {
                            setEditingComment(null)
                            setEditContent('')
                          }}
                          className="px-3 py-1 text-sm text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200"
                        >
                          取消
                        </button>
                        <button
                          onClick={() => handleEditComment(comment.id)}
                          disabled={!editContent.trim()}
                          className="px-3 py-1 text-sm bg-pink-500 text-white rounded hover:bg-pink-600 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                        >
                          保存
                        </button>
                      </div>
                    </div>
                  ) : (
                    <div>
                      <p className="text-gray-700 dark:text-gray-300 mb-3">
                        {comment.content}
                      </p>
                      <div className="flex items-center justify-between">
                        <button
                          onClick={() => handleLikeComment(comment.id)}
                          className={`flex items-center space-x-1 text-sm transition-colors ${
                            comment.is_liked
                              ? 'text-pink-500 hover:text-pink-600'
                              : 'text-gray-500 dark:text-gray-400 hover:text-pink-500'
                          }`}
                        >
                          <Heart className={`w-4 h-4 ${comment.is_liked ? 'fill-current' : ''}`} />
                          <span>{comment.likes_count}</span>
                        </button>

                        {user && comment.user_id === user.id && (
                          <button
                            onClick={() => handleDeleteComment(comment.id)}
                            className="flex items-center space-x-1 text-sm text-gray-500 dark:text-gray-400 hover:text-red-500 transition-colors"
                          >
                            <Trash2 className="w-4 h-4" />
                            <span>删除</span>
                          </button>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  )
}