import { useState } from 'react'
import { useViewHistoryStore } from '../stores/viewHistoryStore'
import { Clock, X, ExternalLink, Trash2 } from 'lucide-react'
import { formatDistanceToNow } from 'date-fns'
import { zhCN } from 'date-fns/locale/zh-CN'

interface ViewHistoryProps {
  onClose: () => void
}

export function ViewHistory({ onClose }: ViewHistoryProps) {
  const { viewHistory, removeViewRecord, clearViewHistory } = useViewHistoryStore()
  const [isClearing, setIsClearing] = useState(false)

  const handleClearAll = async () => {
    if (window.confirm('确定要清空所有浏览记录吗？此操作不可恢复。')) {
      setIsClearing(true)
      try {
        clearViewHistory()
      } finally {
        setIsClearing(false)
      }
    }
  }

  const handleRemoveItem = (id: string) => {
    removeViewRecord(id)
  }

  const handleViewPost = (postId: string) => {
    // 导航到帖子详情页
    window.location.href = `/posts/${postId}`
  }

  if (viewHistory.length === 0) {
    return (
      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg p-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-gray-800 dark:text-gray-200 flex items-center">
            <Clock className="w-5 h-5 mr-2" />
            浏览记录
          </h3>
          <button
            onClick={onClose}
            className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>
        
        <div className="text-center py-8">
          <Clock className="w-12 h-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
          <p className="text-gray-500 dark:text-gray-400">暂无浏览记录</p>
          <p className="text-sm text-gray-400 dark:text-gray-500 mt-1">浏览过的帖子会显示在这里</p>
        </div>
      </div>
    )
  }

  return (
    <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg">
      <div className="p-6 border-b border-gray-200 dark:border-gray-700">
        <div className="flex items-center justify-between">
          <h3 className="text-lg font-semibold text-gray-800 dark:text-gray-200 flex items-center">
            <Clock className="w-5 h-5 mr-2" />
            浏览记录 ({viewHistory.length})
          </h3>
          <div className="flex items-center space-x-2">
            <button
              onClick={handleClearAll}
              disabled={isClearing}
              className="flex items-center px-3 py-1.5 text-sm text-red-600 dark:text-red-400 hover:text-red-700 dark:hover:text-red-300 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
            >
              <Trash2 className="w-4 h-4 mr-1" />
              清空
            </button>
            <button
              onClick={onClose}
              className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>
      </div>

      <div className="max-h-96 overflow-y-auto">
        {viewHistory.map((record) => (
          <div
            key={record.id}
            className="p-4 border-b border-gray-100 dark:border-gray-700 last:border-b-0 hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors group"
          >
            <div className="flex items-start space-x-3">
              {/* 帖子图片缩略图 */}
              {record.postImage ? (
                <img
                  src={record.postImage}
                  alt="帖子图片"
                  className="w-12 h-12 rounded-lg object-cover flex-shrink-0"
                />
              ) : (
                <div className="w-12 h-12 bg-gradient-to-br from-pink-100 to-blue-100 dark:from-pink-900/30 to-blue-900/30 rounded-lg flex items-center justify-center flex-shrink-0">
                  <ExternalLink className="w-5 h-5 text-pink-500 dark:text-pink-400" />
                </div>
              )}

              {/* 内容信息 */}
              <div className="flex-1 min-w-0">
                <div className="flex items-start justify-between">
                  <div className="flex-1 min-w-0">
                    <h4 className="text-sm font-medium text-gray-800 dark:text-gray-200 truncate">
                      {record.postTitle || '无标题'}
                    </h4>
                    {record.postContent && (
                      <p className="text-xs text-gray-600 dark:text-gray-400 mt-1 line-clamp-2">
                        {record.postContent}
                      </p>
                    )}
                    <div className="flex items-center space-x-3 mt-2">
                      {record.authorName && (
                        <div className="flex items-center space-x-1">
                          {record.authorAvatar && (
                            <img
                              src={record.authorAvatar}
                              alt={record.authorName}
                              className="w-4 h-4 rounded-full"
                            />
                          )}
                          <span className="text-xs text-gray-500 dark:text-gray-400">
                            {record.authorName}
                          </span>
                        </div>
                      )}
                      <span className="text-xs text-gray-400 dark:text-gray-500">
                        {formatDistanceToNow(record.timestamp, { 
                          addSuffix: true,
                          locale: zhCN
                        })}
                      </span>
                    </div>
                  </div>

                  {/* 操作按钮 */}
                  <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button
                      onClick={() => handleViewPost(record.postId)}
                      className="p-1.5 text-gray-400 hover:text-blue-500 dark:hover:text-blue-400 rounded-lg hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                      title="查看帖子"
                    >
                      <ExternalLink className="w-3.5 h-3.5" />
                    </button>
                    <button
                      onClick={() => handleRemoveItem(record.id)}
                      className="p-1.5 text-gray-400 hover:text-red-500 dark:hover:text-red-400 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
                      title="删除记录"
                    >
                      <X className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}