import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { PostCard } from '../components/PostCard'
import { CommentSection } from '../components/CommentSection'
import { PostEditModal } from '../components/PostEditModal'
import { ArrowLeft, MoreHorizontal, Edit3, Trash2, Flag, Share2 } from 'lucide-react'
import { Post } from '../types'
import { supabase } from '../lib/supabase'
import { useAuthStore } from '../stores/authStore'
import { useViewHistoryStore } from '../stores/viewHistoryStore'
import { toast } from 'sonner'

export function PostDetailPage() {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const { user } = useAuthStore()
  const { addViewRecord } = useViewHistoryStore()
  
  const [post, setPost] = useState<Post | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [isEditModalOpen, setIsEditModalOpen] = useState(false)
  const [showMenu, setShowMenu] = useState(false)

  const fetchPost = async () => {
    if (!id) return

    try {
      setIsLoading(true)
      
      // 获取帖子详情
      const { data: postData, error: postError } = await supabase
        .from('posts')
        .select(`
          *,
          user:users!user_id(
            id,
            username,
            avatar_url,
            sequential_id
          )
        `)
        .eq('id', id)
        .single()

      if (postError) throw postError

      if (!postData) {
        toast.error('帖子不存在')
        navigate('/')
        return
      }

      // 获取帖子标签
      const { data: tagsData, error: tagsError } = await supabase
        .from('post_tags')
        .select('tag:tags(name, color)')
        .eq('post_id', id)

      if (tagsError) {
        console.warn('获取帖子标签失败:', tagsError)
      }

      // 检查当前用户是否点赞和收藏
      let is_liked = false
      let is_favorited = false

      if (user) {
        // 检查点赞
        const { data: likeData } = await supabase
          .from('likes')
          .select('id')
          .eq('user_id', user.id)
          .eq('post_id', id)
          .maybeSingle()
        
        is_liked = !!likeData

        // 检查收藏
        const { data: favoriteData } = await supabase
          .from('favorites')
          .select('id')
          .eq('user_id', user.id)
          .eq('post_id', id)
          .maybeSingle()
        
        is_favorited = !!favoriteData
      }

      const completePost: Post = {
        ...postData,
        user: postData.user,
        tags: tagsData?.map((pt: any) => pt.tag) || [],
        is_liked,
        is_favorited,
        images: Array.isArray(postData.images) ? postData.images : [],
        videos: Array.isArray(postData.videos) ? postData.videos : [],
        comments_count: postData.comments_count || 0,
        likes_count: postData.likes_count || 0
      }

      setPost(completePost)

      // 添加到浏览历史
      if (user) {
        addViewRecord({
          postId: postData.id,
          postTitle: postData.content?.substring(0, 50) || '无标题',
          postContent: postData.content,
          postImage: postData.images?.[0],
          authorName: postData.user?.username || '未知用户',
          authorAvatar: postData.user?.avatar_url
        })
      }

    } catch (error) {
      console.error('获取帖子详情失败:', error)
      toast.error('获取帖子详情失败')
      navigate('/')
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    fetchPost()
  }, [id, user])

  const handleEditPost = () => {
    setIsEditModalOpen(true)
    setShowMenu(false)
  }

  const handleDeletePost = async () => {
    if (!post || !user || post.user_id !== user.id) return

    if (window.confirm('确定要删除这条帖子吗？此操作不可恢复。')) {
      try {
        const { error } = await supabase
          .from('posts')
          .delete()
          .eq('id', post.id)
          .eq('user_id', user.id)

        if (error) throw error

        toast.success('帖子删除成功')
        navigate('/')
      } catch (error) {
        console.error('删除帖子失败:', error)
        toast.error('删除帖子失败')
      }
    }
    setShowMenu(false)
  }

  const handleSharePost = async () => {
    if (!post) return

    const shareUrl = `${window.location.origin}/posts/${post.id}`
    const shareText = `查看这条有趣的帖子：${post.content?.substring(0, 50)}...`

    try {
      if (navigator.share) {
        await navigator.share({
          title: '二次元小窝 - 帖子分享',
          text: shareText,
          url: shareUrl
        })
      } else {
        // 复制到剪贴板
        await navigator.clipboard.writeText(shareUrl)
        toast.success('链接已复制到剪贴板')
      }
    } catch (error) {
      console.error('分享失败:', error)
      // 降级处理：复制到剪贴板
      try {
        await navigator.clipboard.writeText(shareUrl)
        toast.success('链接已复制到剪贴板')
      } catch (clipboardError) {
        toast.error('分享失败，请手动复制链接')
      }
    }
    setShowMenu(false)
  }

  const handleReportPost = () => {
    toast.info('举报功能开发中...')
    setShowMenu(false)
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-white to-pink-50 dark:from-[var(--bg-secondary)] dark:to-[var(--bg-primary)] p-6">
        <div className="max-w-4xl mx-auto">
          <div className="flex items-center mb-6">
            <button
              onClick={() => navigate(-1)}
              className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors"
            >
              <ArrowLeft className="w-5 h-5" />
            </button>
            <h1 className="text-xl font-semibold ml-4">帖子详情</h1>
          </div>
          <div className="bg-white dark:bg-[var(--bg-card)] rounded-3xl shadow-xl p-8 animate-pulse">
            <div className="space-y-4">
              <div className="flex items-center space-x-3">
                <div className="w-12 h-12 bg-gray-200 dark:bg-gray-700 rounded-full"></div>
                <div className="space-y-2">
                  <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-24"></div>
                  <div className="h-3 bg-gray-200 dark:bg-gray-700 rounded w-16"></div>
                </div>
              </div>
              <div className="space-y-3">
                <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-full"></div>
                <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-3/4"></div>
                <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-1/2"></div>
              </div>
            </div>
          </div>
        </div>
      </div>
    )
  }

  if (!post) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-white to-pink-50 dark:from-[var(--bg-secondary)] dark:to-[var(--bg-primary)] p-6">
        <div className="max-w-4xl mx-auto text-center">
          <div className="bg-white dark:bg-[var(--bg-card)] rounded-3xl shadow-xl p-8">
            <h2 className="text-xl font-semibold text-gray-800 dark:text-white mb-4">帖子不存在</h2>
            <button
              onClick={() => navigate('/')}
              className="bg-pink-500 text-white px-6 py-2 rounded-lg hover:bg-pink-600 transition-colors"
            >
              返回首页
            </button>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-white to-pink-50 dark:from-[var(--bg-secondary)] dark:to-[var(--bg-primary)] p-6">
      <div className="max-w-4xl mx-auto">
        {/* 头部导航 */}
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center">
            <button
              onClick={() => navigate(-1)}
              className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors"
            >
              <ArrowLeft className="w-5 h-5" />
            </button>
            <h1 className="text-xl font-semibold ml-4 text-gray-800 dark:text-white">帖子详情</h1>
          </div>

          {/* 操作菜单 */}
          <div className="relative">
            <button
              onClick={() => setShowMenu(!showMenu)}
              className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors"
            >
              <MoreHorizontal className="w-5 h-5" />
            </button>

            {showMenu && (
              <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-gray-800 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700 z-10">
                <div className="py-1">
                  {user && post.user_id === user.id && (
                    <>
                      <button
                        onClick={handleEditPost}
                        className="flex items-center w-full px-4 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
                      >
                        <Edit3 className="w-4 h-4 mr-2" />
                        编辑帖子
                      </button>
                      <button
                        onClick={handleDeletePost}
                        className="flex items-center w-full px-4 py-2 text-sm text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20"
                      >
                        <Trash2 className="w-4 h-4 mr-2" />
                        删除帖子
                      </button>
                      <hr className="my-1 border-gray-200 dark:border-gray-700" />
                    </>
                  )}
                  <button
                    onClick={handleSharePost}
                    className="flex items-center w-full px-4 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
                  >
                    <Share2 className="w-4 h-4 mr-2" />
                    分享帖子
                  </button>
                  <button
                    onClick={handleReportPost}
                    className="flex items-center w-full px-4 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
                  >
                    <Flag className="w-4 h-4 mr-2" />
                    举报帖子
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* 帖子内容 */}
        <div className="bg-white dark:bg-[var(--bg-card)] rounded-3xl shadow-xl p-8 mb-6">
          <PostCard 
            post={post} 
            onLike={() => fetchPost()}
            onComment={() => {}}
            onShare={handleSharePost}
          />
        </div>

        {/* 评论区 */}
        <div className="bg-white dark:bg-[var(--bg-card)] rounded-3xl shadow-xl p-8">
          <h2 className="text-xl font-semibold text-gray-800 dark:text-white mb-6">评论 ({post.comments_count})</h2>
          <CommentSection postId={post.id} />
        </div>
      </div>

      {/* 编辑模态框 */}
      {isEditModalOpen && (
        <PostEditModal
          post={post}
          isOpen={isEditModalOpen}
          onClose={() => setIsEditModalOpen(false)}
          onSave={() => {
            setIsEditModalOpen(false)
            fetchPost()
          }}
        />
      )}
    </div>
  )
}