import { useState, useEffect } from 'react'
import { PostCard } from '../components/PostCard'
import { CreatePostModal } from '../components/CreatePostModal'
import { PostEditModal } from '../components/PostEditModal'
import { UserMenu } from '../components/UserMenu'
import { SearchBar } from '../components/SearchBar'
import { ThemeToggle } from '../components/ThemeToggle'
import { PullToRefreshIndicator } from '../components/PullToRefreshIndicator'
import { usePullToRefresh } from '../hooks/usePullToRefresh'
import { Post } from '../types'
import { supabase } from '../lib/supabase'
import { toast } from 'sonner'
import { handleDatabaseError } from '../lib/database-utils'

export function HomePage() {
  const [posts, setPosts] = useState<Post[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false)
  const [isEditModalOpen, setIsEditModalOpen] = useState(false)
  const [editingPost, setEditingPost] = useState<Post | null>(null)

  const fetchPosts = async () => {
    let fallbackTimer: number | null = null
    try {
      setIsLoading(true)
      fallbackTimer = window.setTimeout(() => {
        console.log('加载超时，强制停止加载')
        setIsLoading(false)
      }, 5000)
      
      // 获取当前用户信息（可选）
      let user = null
      try {
        const { data: { user: currentUser } } = await supabase.auth.getUser()
        user = currentUser
        console.log('Current user:', user)
      } catch (authError) {
        console.warn('获取用户信息失败:', authError)
        // 继续执行，用户可能未登录
      }
      
      // 首先检查数据库连接
      const { data: connectionTest, error: connectionError } = await supabase
        .from('posts')
        .select('id')
        .limit(1)

      if (connectionError) {
        console.error('数据库连接测试失败:', connectionError)
        throw new Error('数据库连接失败: ' + handleDatabaseError(connectionError, '连接测试'))
      }

      console.log('数据库连接正常，开始获取帖子...')
      
      // 统计帖子总数
      const { count, error: countError } = await supabase
        .from('posts')
        .select('id', { count: 'exact', head: true })

      if (countError) {
        console.error('统计帖子数量失败:', countError)
        // 不中断，继续尝试获取帖子
      }

      const limit = 10
      const total = count || 0
      const maxOffsetBase = Math.max(0, total - limit)
      const randomOffset = maxOffsetBase > 0 ? Math.floor(Math.random() * maxOffsetBase) : 0

      // 随机偏移获取一批帖子
      const { data: postsData, error: postsError } = await supabase
        .from('posts')
        .select('*')
        .order('created_at', { ascending: false })
        .range(randomOffset, randomOffset + limit - 1)

      if (postsError) {
        console.error('获取帖子失败:', postsError)
        throw new Error('获取帖子失败: ' + handleDatabaseError(postsError, '获取帖子'))
      }

      console.log('获取到帖子数量:', postsData?.length || 0)

      if (!postsData || postsData.length === 0) {
        console.log('没有找到帖子数据')
        setPosts([])
        return
      }

      // 获取用户信息和标签信息
      const postsWithDetails = await Promise.all(
        postsData.map(async (post) => {
          try {
            // 获取用户信息
            const { data: userData, error: userError } = await supabase
              .from('users')
              .select('id, username, avatar_url')
              .eq('id', post.user_id)
              .single()

            if (userError) {
              console.warn(`获取用户 ${post.user_id} 信息失败:`, userError)
            }

            // 获取标签信息
            const { data: postTagsData, error: tagsError } = await supabase
              .from('post_tags')
              .select('tag:tags(id, name, category, usage_count)')
              .eq('post_id', post.id)

            if (tagsError) {
              console.warn(`获取帖子 ${post.id} 标签失败:`, tagsError)
            }

            let is_liked = false
            let is_favorited = false

            if (user) {
              try {
                // 检查是否点赞
                const { data: likeData } = await supabase
                  .from('likes')
                  .select('id')
                  .eq('user_id', user.id)
                  .eq('post_id', post.id)
                  .maybeSingle()
                
                is_liked = !!likeData

                // 检查是否收藏
                const { data: favoriteData } = await supabase
                  .from('favorites')
                  .select('id')
                  .eq('user_id', user.id)
                  .eq('post_id', post.id)
                  .maybeSingle()
                
                is_favorited = !!favoriteData
              } catch (authError) {
                console.warn('用户认证检查失败:', authError)
                // 用户可能未登录，继续处理
              }
            }

            return {
              ...post,
              user: userData || { id: post.user_id, username: '未知用户', avatar_url: null },
              tags: postTagsData?.map((pt: any) => pt.tag) || [],
              is_liked,
              is_favorited,
              images: Array.isArray(post.images) ? post.images : [],
              videos: Array.isArray(post.videos) ? post.videos : [],
              comments_count: post.comments_count || 0,
              likes_count: post.likes_count || 0
            }
          } catch (error) {
            console.error(`处理帖子 ${post.id} 时出错:`, error)
            return {
              id: post.id,
              user_id: post.user_id,
              content: post.content || '',
              images: Array.isArray(post.images) ? post.images : [],
              videos: Array.isArray(post.videos) ? post.videos : [],
              likes_count: post.likes_count || 0,
              comments_count: post.comments_count || 0,
              created_at: post.created_at,
              updated_at: post.updated_at,
              user: { id: post.user_id, username: '未知用户', avatar_url: null },
              tags: [],
              is_liked: false,
              is_favorited: false
            }
          }
        })
      )

      console.log('处理完成，设置帖子数据:', postsWithDetails.length)
      const shuffled = [...postsWithDetails]
      for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1))
        const t = shuffled[i]
        shuffled[i] = shuffled[j]
        shuffled[j] = t
      }
      setPosts(shuffled)
    } catch (error) {
      console.error('获取帖子失败:', error)
      const errorMessage = error instanceof Error ? error.message : '获取帖子失败，请稍后重试'
      toast.error(errorMessage)
      // 即使出错也要显示空状态，不要无限加载
      setPosts([])
    } finally {
      if (fallbackTimer !== null) {
        clearTimeout(fallbackTimer)
      }
      setIsLoading(false)
    }
  }

  useEffect(() => {
    // 组件加载时测试数据库连接
    console.log('HomePage 组件加载，开始测试数据库连接...')
    fetchPosts()
  }, [])

  const handlePostSuccess = () => {
    fetchPosts() // 刷新帖子列表
  }

  const handleEditPost = (post: Post) => {
    setEditingPost(post)
    setIsEditModalOpen(true)
  }

  const handlePostUpdated = (updatedPost: Post) => {
    setPosts(prevPosts => 
      prevPosts.map(post => 
        post.id === updatedPost.id ? updatedPost : post
      )
    )
  }

  const handleDeletePost = (postId: string) => {
    setPosts(prevPosts => prevPosts.filter(post => post.id !== postId))
  }

  // 下拉刷新功能
  const { isPulling, isRefreshing, pullProgress, containerRef } = usePullToRefresh({
    onRefresh: fetchPosts,
    threshold: 80,
    maxPull: 120,
    disabled: isLoading
  })

  if (isLoading) {
    return (
      <div ref={containerRef} className="min-h-screen bg-gradient-to-br from-pink-50 to-blue-50 p-6">
        <PullToRefreshIndicator 
          isPulling={isPulling} 
          isRefreshing={isRefreshing} 
          pullProgress={pullProgress} 
        />
        <div className="max-w-4xl mx-auto">
          <div className="grid gap-6">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-white rounded-3xl shadow-lg p-6 animate-pulse">
                <div className="flex items-center space-x-3 mb-4">
                  <div className="w-12 h-12 bg-gray-200 rounded-full"></div>
                  <div className="space-y-2">
                    <div className="h-4 bg-gray-200 rounded w-24"></div>
                    <div className="h-3 bg-gray-200 rounded w-16"></div>
                  </div>
                </div>
                <div className="space-y-3">
                  <div className="h-4 bg-gray-200 rounded w-full"></div>
                  <div className="h-4 bg-gray-200 rounded w-3/4"></div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div ref={containerRef} className="min-h-screen bg-gradient-to-br from-white to-pink-50 dark:from-[var(--bg-secondary)] dark:to-[var(--bg-primary)] pb-20 md:pb-0">
      <PullToRefreshIndicator 
        isPulling={isPulling} 
        isRefreshing={isRefreshing} 
        pullProgress={pullProgress} 
      />
      {/* 桌面端头部导航 */}
      <header className="hidden md:block bg-white dark:bg-gray-900 shadow-sm sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center py-4">
            <div className="flex items-center space-x-4">
              <h1 className="text-2xl font-bold bg-gradient-to-r from-pink-500 to-blue-500 bg-clip-text text-transparent">
                二次元小窝
              </h1>
              <div className="w-96">
                <SearchBar />
              </div>
            </div>
            
            <div className="flex items-center space-x-4">
              <ThemeToggle />
              <button
                onClick={() => setIsCreateModalOpen(true)}
                className="bg-pink-500 text-white px-6 py-2 rounded-full font-semibold hover:bg-pink-600 transform hover:scale-105 transition-all duration-200"
              >
                发布
              </button>
              <UserMenu />
            </div>
          </div>
        </div>
      </header>

      {/* 主要内容 */}
      <main className="max-w-4xl mx-auto p-3 md:p-6 pb-24 md:pb-6">
        {/* 移动端搜索 */}
        <div className="md:hidden mb-4 md:mb-6">
          <SearchBar />
        </div>

        {/* 热门标签 */}
        <div className="mb-6 md:mb-8">
          <h2 className="text-lg md:text-xl font-semibold text-gray-800 dark:text-gray-200 mb-3 md:mb-4">🔥 热门标签</h2>
          <div className="flex flex-wrap gap-2">
            {['动漫', '游戏', 'Cosplay', '插画', '手办'].map((tag) => (
              <button
                key={tag}
                className="px-3 md:px-4 py-1.5 md:py-2 bg-pink-100 dark:bg-pink-900 text-pink-700 dark:text-pink-300 rounded-full text-xs md:text-sm font-medium hover:bg-pink-200 dark:hover:bg-pink-800 transition-all duration-200"
              >
                #{tag}
              </button>
            ))}
          </div>
        </div>

        {/* 帖子列表 */}
        <div className="space-y-4 md:space-y-6">
          {posts.length === 0 ? (
            <div className="text-center py-8 md:py-12">
              <div className="text-4xl md:text-6xl mb-3 md:mb-4">📱</div>
              <h3 className="text-lg md:text-xl font-semibold text-gray-600 dark:text-gray-400 mb-2">还没有内容</h3>
              <p className="text-gray-500 dark:text-gray-500 text-sm md:text-base">成为第一个分享的人吧！</p>
            </div>
          ) : (
            posts.map((post) => (
              <PostCard 
                key={post.id} 
                post={post} 
                onEdit={handleEditPost}
                onDelete={handleDeletePost}
              />
            ))
          )}
        </div>

        {/* 刷新按钮 */}
        <div className="text-center mt-6 md:mt-8">
          <button
            onClick={fetchPosts}
            className="bg-pink-500 text-white px-6 md:px-8 py-2.5 md:py-3 rounded-full font-semibold hover:bg-pink-600 transform hover:scale-105 transition-all duration-200 text-sm md:text-base"
          >
            🔄 换一批
          </button>
        </div>
      </main>

      {/* 发布模态框 */}
      <CreatePostModal
        isOpen={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        onSuccess={handlePostSuccess}
      />

      {/* 编辑模态框 */}
      <PostEditModal
        post={editingPost}
        isOpen={isEditModalOpen}
        onClose={() => {
          setIsEditModalOpen(false)
          setEditingPost(null)
        }}
        onSave={handlePostUpdated}
      />
    </div>
  )
}
