import { useState } from 'react'
import { supabase } from '../lib/supabase'
import { PostCreationTest } from '../components/PostCreationTest'

export function DiagnosticPage() {
  const [testResults, setTestResults] = useState<string[]>([])
  const [isTesting, setIsTesting] = useState(false)

  const addResult = (message: string) => {
    setTestResults(prev => [...prev, `${new Date().toLocaleTimeString()}: ${message}`])
  }

  const runDiagnostics = async () => {
    setIsTesting(true)
    setTestResults([])
    
    try {
      addResult('🚀 开始诊断测试...')
      
      // 1. 测试Supabase客户端
      addResult('1. 测试Supabase客户端配置...')
      if (!supabase) {
        throw new Error('Supabase客户端未初始化')
      }
      addResult('✅ Supabase客户端正常')
      
      // 2. 测试认证状态
      addResult('2. 测试用户认证状态...')
      const { data: { user }, error: authError } = await supabase.auth.getUser()
      if (authError) {
        addResult(`⚠️ 认证错误: ${authError.message}`)
      } else {
        addResult(`✅ 认证状态: ${user ? `已登录 (${user.email})` : '未登录'}`)
      }
      
      // 3. 测试数据库连接
      addResult('3. 测试数据库连接...')
      const { data: connectionTest, error: connectionError } = await supabase
        .from('posts')
        .select('id')
        .limit(1)
      
      if (connectionError) {
        throw new Error(`数据库连接失败: ${connectionError.message}`)
      }
      addResult('✅ 数据库连接正常')
      
      // 4. 测试posts表查询
      addResult('4. 测试posts表查询...')
      const { data: postsData, error: postsError } = await supabase
        .from('posts')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(5)
      
      if (postsError) {
        throw new Error(`Posts查询失败: ${postsError.message}`)
      }
      addResult(`✅ 获取到 ${postsData?.length || 0} 条帖子`)
      
      // 5. 测试users表查询
      addResult('5. 测试users表查询...')
      const { data: usersData, error: usersError } = await supabase
        .from('users')
        .select('*')
        .limit(3)
      
      if (usersError) {
        addResult(`⚠️ Users查询警告: ${usersError.message}`)
      } else {
        addResult(`✅ 获取到 ${usersData?.length || 0} 个用户`)
      }
      
      // 6. 测试完整流程
      if (postsData && postsData.length > 0) {
        addResult('6. 测试完整帖子获取流程...')
        const testPost = postsData[0]
        
        // 获取用户信息
        const { data: userData, error: userError } = await supabase
          .from('users')
          .select('id, username, avatar_url')
          .eq('id', testPost.user_id)
          .single()
        
        if (userError) {
          addResult(`⚠️ 获取用户信息失败: ${userError.message}`)
        } else {
          addResult(`✅ 获取用户信息成功: ${userData?.username}`)
        }
        
        // 获取标签信息
        const { data: postTagsData, error: postTagsError } = await supabase
          .from('post_tags')
          .select('tag:tags(id, name, category, usage_count)')
          .eq('post_id', testPost.id)
        
        if (postTagsError) {
          addResult(`⚠️ 获取标签信息失败: ${postTagsError.message}`)
        } else {
          addResult(`✅ 获取到 ${postTagsData?.length || 0} 个标签`)
        }
      }

      addResult('7. 测试存储桶与头像上传...')
      const urlProbe = supabase.storage.from('avatars').getPublicUrl('probe.txt')
      if (urlProbe?.data?.publicUrl) {
        addResult(`✅ 生成公共URL: ${urlProbe.data.publicUrl}`)
      } else {
        addResult('⚠️ 无法生成公共URL')
      }
      const { data: { user: currentUser } } = await supabase.auth.getUser()
      if (!currentUser) {
        addResult('ℹ️ 未登录，跳过上传测试')
      } else {
        const path = `${currentUser.id}/healthcheck-${Date.now()}.txt`
        const blob = new Blob(['ok'], { type: 'text/plain' })
        const { error: uploadErr } = await supabase.storage.from('avatars').upload(path, blob)
        if (uploadErr) {
          addResult(`❌ 上传失败: ${uploadErr.message}`)
        } else {
          const { data: pub } = supabase.storage.from('avatars').getPublicUrl(path)
          addResult(`✅ 上传成功: ${path}`)
          addResult(`✅ 公共访问: ${pub.publicUrl}`)
        }
      }
      
      addResult('\n🎉 所有诊断测试完成！')
      
    } catch (error) {
      addResult(`\n💥 诊断测试失败: ${error instanceof Error ? error.message : String(error)}`)
    } finally {
      setIsTesting(false)
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-white to-pink-50 p-6 pb-20 md:pb-6">
      <div className="max-w-4xl mx-auto">
        <div className="bg-white rounded-3xl shadow-xl p-8">
          <div className="text-center mb-8">
            <h1 className="text-3xl font-bold bg-gradient-to-r from-purple-600 to-pink-600 bg-clip-text text-transparent mb-4">
              🔧 诊断工具
            </h1>
            <p className="text-gray-600">测试数据库连接和帖子获取功能</p>
          </div>

          <div className="text-center mb-6">
            <button
              onClick={runDiagnostics}
              disabled={isTesting}
              className="bg-gradient-to-r from-purple-500 to-pink-500 text-white px-8 py-3 rounded-full font-semibold hover:from-purple-600 hover:to-pink-600 transform hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isTesting ? '🔄 测试中...' : '🚀 开始诊断'}
            </button>
          </div>

          {testResults.length > 0 && (
            <div className="bg-gray-50 rounded-2xl p-6">
              <h3 className="text-lg font-semibold text-gray-800 mb-4">📊 测试结果:</h3>
              <div className="space-y-2 max-h-96 overflow-y-auto">
                {testResults.map((result, index) => (
                  <div key={index} className="text-sm font-mono text-gray-700 bg-white p-3 rounded-lg border">
                    {result}
                  </div>
                ))}
              </div>
            </div>
          )}
          
          <div className="mt-8">
            <PostCreationTest />
          </div>
        </div>
        
        <div className="text-center mt-8">
          <a 
            href="/" 
            className="text-purple-600 hover:text-purple-800 font-medium underline transition-colors duration-200"
          >
            返回首页
          </a>
        </div>
      </div>
    </div>
  )
}