import { useState, useRef } from 'react'
import { supabase, supabaseConfig } from '../lib/supabase'
import { toast } from 'sonner'
import { X, Upload, Hash } from 'lucide-react'

interface CreatePostModalProps {
  isOpen: boolean
  onClose: () => void
  onSuccess?: () => void
}

export function CreatePostModal({ isOpen, onClose, onSuccess }: CreatePostModalProps) {
  const [content, setContent] = useState('')
  const [images, setImages] = useState<string[]>([])
  const [videos, setVideos] = useState<string[]>([])
  const [tags, setTags] = useState<string[]>([])
  const [newTag, setNewTag] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [uploadProgress, setUploadProgress] = useState<Record<string, number>>({})
  const fileInputRef = useRef<HTMLInputElement>(null)

  if (!isOpen) return null

  const handleMediaUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files
    if (!files) return

    setIsLoading(true)
    
    try {
      const uploadPromises = Array.from(files).map(async (file) => {
        // 验证文件类型
        const allowedImageTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp', 'image/gif']
        const allowedVideoTypes = ['video/mp4', 'video/webm', 'video/quicktime', 'video/mov']
        const allowedTypes = [...allowedImageTypes, ...allowedVideoTypes]
        
        if (!allowedTypes.includes(file.type)) {
          throw new Error(`不支持的文件类型: ${file.type}`)
        }

        // 验证文件大小
        const maxImageSize = 10 * 1024 * 1024 // 10MB for images
        const maxVideoSize = 50 * 1024 * 1024 // 50MB for videos
        const maxSize = allowedImageTypes.includes(file.type) ? maxImageSize : maxVideoSize
        
        if (file.size > maxSize) {
          const fileType = allowedImageTypes.includes(file.type) ? '图片' : '视频'
          throw new Error(`${fileType}大小不能超过 ${maxSize / (1024 * 1024)}MB`)
        }

        const fileName = `${Date.now()}-${file.name}`
        const filePath = `${fileName}`
        
        // 上传文件
        console.log('开始上传文件:', fileName, '到存储桶: posts')
        const { error: uploadError } = await supabase.storage
          .from('posts')
          .upload(filePath, file, {
            cacheControl: '3600',
            upsert: false
          })

        if (uploadError) {
          console.error('上传错误详情:', uploadError)
          console.error('错误消息:', uploadError.message)
          
          if (uploadError.message.includes('bucket')) {
            throw new Error('存储桶配置错误，请联系管理员')
          } else if (uploadError.message.includes('permission')) {
            throw new Error('权限不足，无法上传文件')
          } else if (uploadError.message.includes('Row Level Security')) {
            throw new Error('安全策略阻止上传，请联系管理员')
          } else {
            throw new Error(`文件上传失败: ${uploadError.message}`)
          }
        }

        // 获取公共URL
        const { data: urlData } = supabase.storage
          .from('posts')
          .getPublicUrl(filePath)

        if (!urlData?.publicUrl) {
          throw new Error('无法获取文件URL')
        }

        return { url: urlData.publicUrl, type: file.type }
      })

      const uploadedMedia = await Promise.all(uploadPromises)
      
      // 分别处理图片和视频
      const imageUrls = uploadedMedia.filter(media => media.type.startsWith('image/')).map(media => media.url)
      const videoUrls = uploadedMedia.filter(media => media.type.startsWith('video/')).map(media => media.url)
      
      if (imageUrls.length > 0) {
        setImages(prev => [...prev, ...imageUrls])
      }
      if (videoUrls.length > 0) {
        setVideos(prev => [...prev, ...videoUrls])
      }
      
      const totalFiles = uploadedMedia.length
      const imageCount = imageUrls.length
      const videoCount = videoUrls.length
      
      if (imageCount > 0 && videoCount > 0) {
        toast.success(`成功上传 ${imageCount} 张图片和 ${videoCount} 个视频`)
      } else if (imageCount > 0) {
        toast.success(`成功上传 ${imageCount} 张图片`)
      } else if (videoCount > 0) {
        toast.success(`成功上传 ${videoCount} 个视频`)
      }
    } catch (error) {
      console.error('上传失败:', error)
      const errorMessage = error instanceof Error ? error.message : '文件上传失败，请重试'
      toast.error(errorMessage)
    } finally {
      setIsLoading(false)
      // 清空input值，允许重复选择同一文件
      event.target.value = ''
    }
  }

  const removeImage = (index: number) => {
    setImages(prev => prev.filter((_, i) => i !== index))
  }

  const removeVideo = (index: number) => {
    setVideos(prev => prev.filter((_, i) => i !== index))
  }

  const addTag = () => {
    if (newTag.trim() && !tags.includes(newTag.trim())) {
      setTags(prev => [...prev, newTag.trim()])
      setNewTag('')
    }
  }

  const removeTag = (tagToRemove: string) => {
    setTags(prev => prev.filter(tag => tag !== tagToRemove))
  }

  const handleSubmit = async () => {
    if (!content.trim() && images.length === 0 && videos.length === 0) {
      toast.error('请输入内容或上传媒体文件')
      return
    }

    setIsLoading(true)

    try {
      // 检查用户登录状态
      const { data: { user }, error: authError } = await supabase.auth.getUser()
      
      if (authError || !user) {
        console.error('用户认证错误:', authError)
        toast.error('请先登录后再发布帖子')
        setIsLoading(false)
        return
      }

      console.log('当前用户ID:', user.id)
      console.log('发布内容:', content.trim())
      console.log('图片数量:', images.length)
      console.log('视频数量:', videos.length)

      // 创建帖子数据
      const postData = {
        user_id: user.id,
        content: content.trim() || null,
        images: images.length > 0 ? images : [],
        videos: videos.length > 0 ? videos : []
      }

      console.log('准备插入的帖子数据:', postData)

      // 创建帖子
      const { data: post, error: postError } = await supabase
        .from('posts')
        .insert(postData)
        .select()
        .single()

      if (postError) {
        console.error('创建帖子失败:', postError)
        console.error('错误详情:', JSON.stringify(postError, null, 2))
        throw new Error(`创建帖子失败: ${postError.message}`)
      }

      // 处理标签（简化版本，避免权限问题）
      if (tags.length > 0) {
        try {
          for (const tagName of tags) {
            // 检查标签是否存在
            const { data: existingTag, error: checkError } = await supabase
              .from('tags')
              .select('id')
              .eq('name', tagName)
              .single()

            let tagId
            if (existingTag) {
              tagId = existingTag.id
            } else {
              // 创建新标签
              const { data: newTag, error: createError } = await supabase
                .from('tags')
                .insert({ name: tagName })
                .select()
                .single()
              
              if (createError) {
                console.warn(`创建标签 ${tagName} 失败:`, createError)
                continue // 跳过失败的标签
              }
              tagId = newTag?.id
            }

            if (tagId) {
              // 关联帖子和标签
              const { error: linkError } = await supabase
                .from('post_tags')
                .insert({
                  post_id: post.id,
                  tag_id: tagId
                })
              
              if (linkError) {
                console.warn(`关联标签 ${tagName} 失败:`, linkError)
              }
            }
          }
        } catch (tagError) {
          console.warn('处理标签时出错:', tagError)
          // 标签处理失败不影响帖子创建
        }
      }

      toast.success('发布成功！')
      onSuccess?.()
      onClose()
      
      // 重置表单
      setContent('')
      setImages([])
      setVideos([])
      setTags([])
    } catch (error) {
      console.error('发布帖子失败:', error)
      let errorMessage = '发布失败'
      
      if (error instanceof Error) {
        errorMessage = error.message
        if (errorMessage.includes('violates')) {
          errorMessage = '数据验证失败，请检查输入内容'
        } else if (errorMessage.includes('permission')) {
          errorMessage = '权限不足，无法发布帖子'
        } else if (errorMessage.includes('Row Level Security')) {
          errorMessage = '安全策略阻止发布，请联系管理员'
        } else if (errorMessage.includes('未登录')) {
          errorMessage = '请先登录后再发布'
        }
      }
      
      toast.error(errorMessage)
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden">
        {/* 头部 */}
        <div className="flex items-center justify-between p-6 border-b border-gray-200 dark:border-gray-600">
          <h2 className="text-xl font-semibold text-gray-800 dark:text-gray-200">发布新帖子</h2>
          <button
            onClick={onClose}
            className="text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200 transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* 内容区域 */}
        <div className="p-6 overflow-y-auto max-h-[calc(90vh-200px)]">
          {/* 文本输入 */}
          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              分享你的想法
            </label>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-xl focus:ring-2 focus:ring-pink-500 focus:border-transparent resize-none bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-200"
              rows={4}
              placeholder="今天有什么想分享的吗？"
            />
          </div>

          {/* 媒体上传 */}
          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              添加图片或视频
            </label>
            <div className="grid grid-cols-4 gap-2">
              {/* 图片预览 */}
              {images.map((image, index) => (
                <div key={`img-${index}`} className="relative aspect-square rounded-xl overflow-hidden">
                  <img
                    src={image}
                    alt={`图片 ${index + 1}`}
                    className="w-full h-full object-cover"
                  />
                  <button
                    onClick={() => removeImage(index)}
                    className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 hover:bg-red-600 transition-colors"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </div>
              ))}
              
              {/* 视频预览 */}
              {videos.map((video, index) => (
                <div key={`video-${index}`} className="relative aspect-square rounded-xl overflow-hidden bg-gray-100 dark:bg-gray-700">
                  <video
                    src={video}
                    className="w-full h-full object-cover"
                    controls
                    muted
                  />
                  <button
                    onClick={() => removeVideo(index)}
                    className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 hover:bg-red-600 transition-colors z-10"
                  >
                    <X className="w-3 h-3" />
                  </button>
                  <div className="absolute bottom-1 left-1 bg-black bg-opacity-70 text-white text-xs px-1 py-0.5 rounded">
                    视频
                  </div>
                </div>
              ))}
              
              {(images.length + videos.length) < 9 && (
                <label className="aspect-square border-2 border-dashed border-gray-300 rounded-xl flex items-center justify-center cursor-pointer hover:border-pink-500 transition-colors">
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept="image/*,video/*"
                    multiple
                    onChange={handleMediaUpload}
                    className="hidden"
                  />
                  <Upload className="w-8 h-8 text-gray-400" />
                </label>
              )}
            </div>
          </div>

          {/* 标签输入 */}
          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              添加标签
            </label>
            <div className="flex items-center space-x-2 mb-2">
              <Hash className="w-5 h-5 text-gray-400" />
              <input
                type="text"
                value={newTag}
                onChange={(e) => setNewTag(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && addTag()}
                className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-xl focus:ring-2 focus:ring-pink-500 focus:border-transparent bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-200"
                placeholder="输入标签名称"
              />
              <button
                onClick={addTag}
                className="px-4 py-2 bg-gradient-to-r from-pink-500 to-blue-500 text-white rounded-xl font-medium hover:from-pink-600 hover:to-blue-600 transition-all duration-200"
              >
                添加
              </button>
            </div>
            
            <div className="flex flex-wrap gap-2">
              {tags.map((tag) => (
                <span
                  key={tag}
                  className="px-3 py-1 bg-gradient-to-r from-pink-100 to-blue-100 text-pink-700 rounded-full text-sm font-medium flex items-center space-x-1"
                >
                  <span>#{tag}</span>
                  <button
                    onClick={() => removeTag(tag)}
                    className="text-pink-500 hover:text-pink-700"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </span>
              ))}
            </div>
          </div>
        </div>

        {/* 底部按钮 */}
        <div className="flex items-center justify-end space-x-4 p-6 border-t">
          <button
            onClick={onClose}
            className="px-6 py-2 text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200 transition-colors"
          >
            取消
          </button>
          <button
            onClick={handleSubmit}
            disabled={isLoading || (!content.trim() && images.length === 0)}
            className="px-8 py-2 bg-gradient-to-r from-pink-500 to-blue-500 text-white rounded-xl font-semibold hover:from-pink-600 hover:to-blue-600 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200"
          >
            {isLoading ? '发布中...' : '发布'}
          </button>
        </div>
      </div>
    </div>
  )
}