import { useState } from 'react'
import { LogOut, User, Settings, Heart, Wrench } from 'lucide-react'
import { Link } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { useAuthStore } from '../stores/authStore'
import { toast } from 'sonner'

interface UserMenuProps {
  className?: string
}

export function UserMenu({ className }: UserMenuProps) {
  const [isOpen, setIsOpen] = useState(false)
  const { user } = useAuthStore()

  const handleLogout = async () => {
    try {
      const { error } = await supabase.auth.signOut()
      if (error) throw error
      toast.success('退出登录成功')
      setIsOpen(false)
    } catch (error) {
      toast.error('退出登录失败')
    }
  }

  if (!user) return null

  return (
    <div className={`relative ${className}`}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center space-x-2 p-2 rounded-full hover:bg-gray-100 transition-colors"
      >
        <img
          src={user.user_metadata?.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.email}`}
          alt="用户头像"
          className="w-8 h-8 rounded-full object-cover"
        />
        <span className="text-sm font-medium text-gray-700">
          {user.user_metadata?.username || user.email?.split('@')[0]}
        </span>
      </button>

      {isOpen && (
        <div className="absolute right-0 mt-2 w-48 bg-white rounded-2xl shadow-lg border z-50">
          <div className="p-2">
            <button className="w-full flex items-center space-x-3 px-3 py-2 text-left text-sm text-gray-700 hover:bg-gray-100 rounded-xl transition-colors">
              <User className="w-4 h-4" />
              <span>个人主页</span>
            </button>
            
            <button className="w-full flex items-center space-x-3 px-3 py-2 text-left text-sm text-gray-700 hover:bg-gray-100 rounded-xl transition-colors">
              <Heart className="w-4 h-4" />
              <span>我的收藏</span>
            </button>
            
            <button className="w-full flex items-center space-x-3 px-3 py-2 text-left text-sm text-gray-700 hover:bg-gray-100 rounded-xl transition-colors">
              <Settings className="w-4 h-4" />
              <span>设置</span>
            </button>
            
            <Link 
              to="/diagnostic" 
              className="w-full flex items-center space-x-3 px-3 py-2 text-left text-sm text-gray-700 hover:bg-gray-100 rounded-xl transition-colors"
              onClick={() => setIsOpen(false)}
            >
              <Wrench className="w-4 h-4" />
              <span>诊断工具</span>
            </Link>
            
            <hr className="my-2" />
            
            <button
              onClick={handleLogout}
              className="w-full flex items-center space-x-3 px-3 py-2 text-left text-sm text-red-600 hover:bg-red-50 rounded-xl transition-colors"
            >
              <LogOut className="w-4 h-4" />
              <span>退出登录</span>
            </button>
          </div>
        </div>
      )}
    </div>
  )
}